'use client'

import * as React from 'react'

/** Pasta pública das fotos de demo — incluída no registry/API para o mirror. */
export const POLAROID_DEMO_PHOTOS = '/polaroid-line-carousel'

/*
 * Polaroid Line Carousel — fotos instantâneas presas por pregadores num varal que
 * cede no meio. Arraste o varal (ou use as setas) e as fotos deslizam por ele,
 * balançando nos pregadores com a velocidade que você der e voltando ao lugar com
 * um leve passo além; mesmo paradas, elas balançam numa brisa. A do meio é a que
 * está à vista.
 *
 * Arrastar, clicar numa foto, ←/→ e autoplay. Slide sem `image` ganha uma
 * paisagem pintada, então funciona sem arquivo nenhum.
 */

export type LandPalette = 'dawn' | 'alpine' | 'dusk' | 'mist'

export type Slide = {
  image?: string
  title?: string
  caption?: string
  alt?: string
  /** Paleta e semente da paisagem pintada quando `image` está vazio. */
  palette?: LandPalette
  seed?: number
}

export type PolaroidLineCarouselProps = {
  slides?: Slide[]
  /** Qualquer medida do CSS. Padrão: 100svh. */
  height?: number | string
  /** Largura de uma foto em px (ela encolhe em espaços estreitos). */
  cardWidth?: number
  /** Quanto o varal cede no meio, em px. */
  sag?: number
  /** Quanto as fotos balançam; 0 as deixa paradas. */
  swing?: number
  /** ms por foto; 0 desliga o autoplay. Ele espera enquanto alguém mexe no varal. */
  autoplay?: number
  /** Cor do varal. */
  string?: string
  background?: string
  ink?: string
  /** Textos dos botões e do leitor de tela. */
  labels?: Partial<PolaroidLineLabels>
  onChange?: (index: number) => void
  className?: string
  style?: React.CSSProperties
  ariaLabel?: string
}

export type PolaroidLineLabels = {
  previous: string
  next: string
  /** O aviso do leitor de tela: a foto à vista (a partir de 1), o total e o título. */
  status: (index: number, total: number, title?: string) => string
}

const DEFAULT_LABELS: PolaroidLineLabels = {
  previous: 'Anterior',
  next: 'Próxima',
  status: (index, total, title) => 'Foto ' + index + ' de ' + total + (title ? ': ' + title : ''),
}

// #region lógica
export function wrap(i: number, n: number): number {
  return n ? ((i % n) + n) % n : 0
}

export function clamp(v: number, a: number, b: number): number {
  return Math.min(b, Math.max(a, v))
}

/** Altura de um varal que cede `sag` entre (0, y0) e (w, y0), no ponto x. */
export function stringY(x: number, w: number, y0: number, sag: number): number {
  const t = clamp(x / w, 0, 1)
  return y0 + 4 * sag * t * (1 - t)
}

/** Um passo de uma mola com amortecimento crítico até o alvo. */
export function springStep(
  x: number,
  v: number,
  target: number,
  dt: number,
  k = 70,
): [number, number] {
  const c = 2 * Math.sqrt(k)
  const nv = v + (k * (target - x) - c * v) * dt
  return [x + nv * dt, nv]
}

/** Um passo do balanço de uma foto. lineVel é a velocidade das fotos no varal (px/s, + = para a direita); a foto fica para trás do movimento, a gravidade a puxa de volta e o atrito a amortece. */
export function swingStep(
  a: number,
  w: number,
  lineVel: number,
  dt: number,
  gain: number,
): [number, number] {
  const nw = w + (-38 * a - 4.2 * w + lineVel * 0.0034 * gain) * dt
  return [clamp(a + nw * dt, -0.6, 0.6), nw]
}

/** Índice da foto mais perto do meio para um deslocamento do varal. */
export function nearestAt(off: number, spacing: number, n: number): number {
  return clamp(Math.round(off / spacing), 0, Math.max(0, n - 1))
}

export function pad2(n: number): string {
  return n < 10 ? '0' + n : String(n)
}

/** Quanto o elemento está encolhido ou ampliado na tela por um transform em volta (1 sem transform). */
function screenScale(el: HTMLElement): number {
  return el.offsetWidth ? el.getBoundingClientRect().width / el.offsetWidth || 1 : 1
}
// #endregion lógica

/* ------------------------------------------------------- paisagens pintadas */

const PALETTES = {
  dawn: {
    top: '#e7b7a5',
    bottom: '#f8e8d6',
    sun: '#fff4df',
    far: '#d2b2bb',
    near: '#3a2a3b',
    mist: '255,240,232',
  },
  alpine: {
    top: '#7ea5c8',
    bottom: '#e3ecf2',
    sun: '#ffffff',
    far: '#a9bfd0',
    near: '#1c3044',
    mist: '236,244,250',
  },
  dusk: {
    top: '#2a2450',
    bottom: '#ef8d60',
    sun: '#ffd9a6',
    far: '#93607c',
    near: '#18121f',
    mist: '255,196,160',
  },
  mist: {
    top: '#c4d0cb',
    bottom: '#eef1ec',
    sun: '#ffffff',
    far: '#aebcb5',
    near: '#2c3a33',
    mist: '246,248,245',
  },
}

function mulberry32(seed: number): () => number {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6d2b79f5) >>> 0
    let t = a
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}
function hexRgb(h: string): [number, number, number] {
  const v = parseInt(h.replace('#', ''), 16)
  return [(v >> 16) & 255, (v >> 8) & 255, v & 255]
}
function mixRgb(a: string, b: string, t: number): string {
  const A = hexRgb(a)
  const B = hexRgb(b)
  return 'rgb(' + A.map((v, i) => Math.round(v + (B[i] - v) * t)).join(',') + ')'
}

// Uma paisagem de serras em camadas: o céu, um sol baixo, cinco serras sumindo na
// névoa com bruma entre elas, pinheiros na mais perto e o grão do filme. Pintada uma vez.
function paintLandscape(seed: number, palette: LandPalette, w = 1600, h = 1000): string {
  if (typeof document === 'undefined') return ''
  const c = document.createElement('canvas')
  c.width = w
  c.height = h
  const g = c.getContext('2d')
  if (!g) return ''
  const P = PALETTES[palette] ?? PALETTES.dawn
  const r = mulberry32(seed * 104729 + 7)

  const sky = g.createLinearGradient(0, 0, 0, h * 0.72)
  sky.addColorStop(0, P.top)
  sky.addColorStop(1, P.bottom)
  g.fillStyle = sky
  g.fillRect(0, 0, w, h)
  const sx = w * (0.22 + r() * 0.56)
  const sy = h * (0.26 + r() * 0.16)
  const halo = g.createRadialGradient(sx, sy, 0, sx, sy, w * 0.45)
  halo.addColorStop(0, 'rgba(' + hexRgb(P.sun).join(',') + ',.85)')
  halo.addColorStop(0.08, 'rgba(' + hexRgb(P.sun).join(',') + ',.55)')
  halo.addColorStop(1, 'rgba(' + hexRgb(P.sun).join(',') + ',0)')
  g.fillStyle = halo
  g.fillRect(0, 0, w, h)
  g.fillStyle = P.sun
  g.beginPath()
  g.arc(sx, sy, h * 0.045, 0, Math.PI * 2)
  g.fill()

  const layers = 5
  for (let L = 0; L < layers; L++) {
    const k = L / (layers - 1)
    const base = h * (0.42 + k * 0.4)
    const amp = h * (0.07 + k * 0.1)
    const ph = [r(), r(), r(), r()].map((v) => v * Math.PI * 2)
    const fr = [1.3 + r(), 3.1 + r() * 2, 7 + r() * 4, 17 + r() * 8]
    const ridge = (x: number) => {
      const u = x / w
      return (
        base -
        amp *
          (0.55 * Math.sin(u * fr[0] + ph[0]) +
            0.28 * Math.sin(u * fr[1] + ph[1]) +
            0.12 * Math.abs(Math.sin(u * fr[2] + ph[2])) +
            0.05 * Math.sin(u * fr[3] + ph[3]))
      )
    }
    const mist = g.createLinearGradient(0, base - amp * 1.4, 0, base + amp * 0.4)
    mist.addColorStop(0, 'rgba(' + P.mist + ',0)')
    mist.addColorStop(1, 'rgba(' + P.mist + ',' + (0.55 - k * 0.35).toFixed(2) + ')')
    g.fillStyle = mist
    g.fillRect(0, base - amp * 1.4, w, amp * 1.8)
    const body = g.createLinearGradient(0, base - amp, 0, h)
    body.addColorStop(0, mixRgb(P.far, P.near, Math.pow(k, 1.3)))
    body.addColorStop(1, mixRgb(P.far, P.near, Math.min(1, Math.pow(k, 1.3) + 0.18)))
    g.fillStyle = body
    g.beginPath()
    g.moveTo(0, h)
    for (let x = 0; x <= w; x += 6) g.lineTo(x, ridge(x))
    g.lineTo(w, h)
    g.closePath()
    g.fill()
    if (L >= layers - 2) {
      g.fillStyle = mixRgb(P.far, P.near, Math.min(1, Math.pow(k, 1.3) + 0.08))
      for (let x = 0; x < w; x += 7 + r() * 9) {
        if (r() < 0.35) continue
        const y = ridge(x) + 2
        const th = h * (0.025 + r() * 0.035) * (0.6 + k)
        const tw = th * 0.32
        g.beginPath()
        g.moveTo(x, y - th)
        g.lineTo(x + tw, y)
        g.lineTo(x - tw, y)
        g.closePath()
        g.fill()
      }
    }
  }

  const vig = g.createRadialGradient(w / 2, h * 0.45, h * 0.3, w / 2, h / 2, w * 0.78)
  vig.addColorStop(0, 'rgba(0,0,0,0)')
  vig.addColorStop(1, 'rgba(0,0,0,.32)')
  g.fillStyle = vig
  g.fillRect(0, 0, w, h)
  const grain = g.getImageData(0, 0, w, h)
  const d = grain.data
  for (let i = 0; i < d.length; i += 4) {
    const v = (r() - 0.5) * 14
    d[i] += v
    d[i + 1] += v
    d[i + 2] += v
  }
  g.putImageData(grain, 0, 0)
  return c.toDataURL('image/jpeg', 0.88)
}

const DEFAULT_SLIDES: Slide[] = [
  {
    title: 'Primeira luz',
    caption: 'A névoa saindo das serras do leste.',
    palette: 'dawn',
    seed: 3,
  },
  {
    title: 'Passo alto',
