    seed: 21,
  },
  { title: 'Serra rosa', caption: 'Cinco serras, um suspiro longo.', palette: 'dawn', seed: 34 },
  {
    title: 'Hora azul',
    caption: 'Os pinheiros escurecendo contra a neve.',
    palette: 'alpine',
    seed: 55,
  },
]

// Cada slide como o endereço de uma imagem; os sem imagem são pintados no primeiro quadro depois de montar.
function useSlideImages(slides: Slide[]): string[] {
  const key = slides.map((s) => s.image || (s.palette || 'dawn') + ':' + (s.seed ?? 1)).join('|')
  const [painted, setPainted] = React.useState<{ key: string; srcs: string[] }>({
    key: '',
    srcs: [],
  })
  React.useEffect(() => {
    if (slides.every((s) => s.image)) return
    const id = requestAnimationFrame(() =>
      setPainted({
        key,
        srcs: slides.map((s, i) =>
          s.image ? '' : paintLandscape(s.seed ?? i + 1, s.palette || 'dawn'),
        ),
      }),
    )
    return () => cancelAnimationFrame(id)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key])
  return slides.map((s, i) => s.image || (painted.key === key ? painted.srcs[i] : '') || '')
}

