// O React 19 sobe uma <style> com href e precedence para o <head>, uma vez só para todos os varais. O React 18 não
// conhece isso: lá ela vai dentro do varal, escondida e com o CSS cru, porque como filho de texto o SSR do 18 escaparia
// as aspas e quebraria os seletores.
const HOISTS_STYLES = Number(React.version.split('.')[0]) >= 19

function PolaroidLineStyles() {
  if (HOISTS_STYLES) {
    const hoist = {
      href: 'polaroid-line-carousel',
      precedence: 'default',
    } as React.StyleHTMLAttributes<HTMLStyleElement>
    return <style {...hoist}>{PL_CSS}</style>
  }
  return <style hidden dangerouslySetInnerHTML={{ __html: PL_CSS }} />
}

export default function PolaroidLineCarousel({
  slides = DEFAULT_SLIDES,
  height = '100svh',
  cardWidth = 300,
  sag = 46,
  swing = 1,
  autoplay = 4500,
  string = '#8a7f72',
  background = 'var(--color-background, #efece6)',
  ink = 'var(--color-foreground, #161513)',
  labels,
  onChange,
  className,
  style,
  ariaLabel = 'Carrossel de fotos',
}: PolaroidLineCarouselProps) {
  const n = slides.length
  const L = { ...DEFAULT_LABELS, ...labels }
  const srcs = useSlideImages(slides)
  const [active, setActive] = React.useState(0)
  const [dragging, setDragging] = React.useState(false)
  // w = 0 até medir: as fotos ficam escondidas até lá, em vez de aparecerem num tamanho errado
  const [size, setSize] = React.useState({ w: 0, h: 0, cw: cardWidth })
  const rootRef = React.useRef<HTMLDivElement>(null)
  const pathRef = React.useRef<SVGPathElement>(null)
  const cards = React.useRef<(HTMLDivElement | null)[]>([])
  const sim = React.useRef({ off: 0, vel: 0, target: 0, a: [] as number[], w: [] as number[] })
  const drag = React.useRef<null | {
    x: number
    off: number
    lx: number
    lt: number
    v: number
    k: number
    moved: boolean
  }>(null)
  const lastTouch = React.useRef(0)
  const activeRef = React.useRef(0)
  const opts = React.useRef({ sag, swing })
  React.useEffect(() => {
    opts.current = { sag, swing }
  }, [sag, swing])

  const spacing = size.cw * 1.08
  const goTo = React.useCallback(
    (i: number) => {
      sim.current.target = clamp(i, 0, n - 1) * spacing
    },
    [n, spacing],
  )

  // o tamanho do próprio varal, sem a escala de um transform em volta (clientWidth, não getBoundingClientRect)
  React.useEffect(() => {
    const root = rootRef.current
    if (!root) return
    const measure = () => {
      const w = root.clientWidth
      const h = root.clientHeight
      const cw = Math.round(Math.max(150, Math.min(cardWidth, w * 0.42, h * 0.42)))
      setSize((s) => (s.w === w && s.h === h && s.cw === cw ? s : { w, h, cw }))
    }
    const ro = new ResizeObserver(measure)
    ro.observe(root)
    return () => ro.disconnect()
  }, [cardWidth])

  // o alvo continua na foto à vista quando o espaçamento muda
  React.useEffect(() => {
    sim.current.target = activeRef.current * spacing
    sim.current.off = activeRef.current * spacing
  }, [spacing])

  React.useEffect(() => {
    onChange?.(active)
  }, [active, onChange])

  // a simulação, escrita direto no DOM a cada quadro
  React.useEffect(() => {
    const root = rootRef.current
    if (!root || !size.w) return
    const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches
    let visible = true
    let raf = 0
    let prev = performance.now()
    const S = sim.current
    const frame = (now: number) => {
      raf = 0
      if (!visible) return
      const dt = Math.min(0.033, (now - prev) / 1000)
      prev = now
      const { w, h, cw } = size
      const y0 = Math.max(40, h * 0.2)
      const d = drag.current
      let lineVel: number
      if (d && d.moved) {
        lineVel = d.v * 1000
      } else {
        const before = S.off
        ;[S.off, S.vel] = springStep(S.off, S.vel, S.target, dt)
        lineVel = -(S.off - before) / Math.max(dt, 1e-3)
      }
      const o = opts.current
      const g = reduce ? 0 : o.swing
      const near = nearestAt(S.off, spacing, n)
      for (let i = 0; i < n; i++) {
        const el = cards.current[i]
        if (!el) continue
        const x = w / 2 + i * spacing - S.off
        if (x < -cw * 1.5 || x > w + cw * 1.5) {
          el.style.visibility = 'hidden'
          continue
        }
        el.style.visibility = 'visible'
        let a = S.a[i] || 0
        let av = S.w[i] || 0
        ;[a, av] = swingStep(a, av, lineVel, dt, g)
        if (g) a += Math.sin(now / 1300 + i * 1.7) * 0.0009 * g
        S.a[i] = a
        S.w[i] = av
        const y = stringY(x, w, y0, o.sag) - 6
        el.style.transform =
          'translate(' +
          (x - cw / 2).toFixed(1) +
          'px,' +
          y.toFixed(1) +
          'px) rotate(' +
          a.toFixed(4) +
          'rad)'
        el.style.zIndex = String(i === near ? n + 1 : n - Math.abs(i - near))
      }
      pathRef.current?.setAttribute(
        'd',
        'M0 ' + y0 + ' Q' + w / 2 + ' ' + (y0 + 2 * o.sag) + ' ' + w + ' ' + y0,
      )
      if (near !== activeRef.current) {
        activeRef.current = near
        setActive(near)
      }
      raf = requestAnimationFrame(frame)
    }
    const io = new IntersectionObserver(([e]) => {
      visible = e.isIntersecting
      if (visible && !raf) {
        prev = performance.now()
        raf = requestAnimationFrame(frame)
      }
    })
    io.observe(root)
    raf = requestAnimationFrame(frame)
    return () => {
      cancelAnimationFrame(raf)
      io.disconnect()
    }
  }, [size, spacing, n])

  // autoplay, de volta à primeira foto depois da última
  React.useEffect(() => {
    if (!autoplay || n < 2) return
    const t = window.setInterval(() => {
      if (document.hidden || drag.current || performance.now() - lastTouch.current < autoplay)
        return
      goTo(activeRef.current >= n - 1 ? 0 : activeRef.current + 1)
    }, autoplay)
    return () => window.clearInterval(t)
  }, [autoplay, n, goTo])

  // o ponteiro anda em px da tela; o varal, nos do próprio layout: k desconta a escala de um transform em volta
  const onDown = (e: React.PointerEvent) => {
    if (e.button > 0 || (e.target as HTMLElement).closest('.pl-bar')) return
    lastTouch.current = performance.now()
    const k = rootRef.current ? screenScale(rootRef.current) : 1
    drag.current = {
      x: e.clientX,
      off: sim.current.off,
      lx: e.clientX,
      lt: e.timeStamp,
      v: 0,
      k,
      moved: false,
    }
  }
  const onMove = (e: React.PointerEvent) => {
    const d = drag.current
    if (!d) return
    const dx = (e.clientX - d.x) / d.k
    if (!d.moved && Math.abs(dx) * d.k > 5) {
      d.moved = true
      setDragging(true)
      try {
        rootRef.current?.setPointerCapture(e.pointerId)
      } catch {
        // o ponteiro já foi embora: o arraste segue sem a captura
      }
    }
    if (!d.moved) return
    const dt = Math.max(1, e.timeStamp - d.lt)
    d.v = 0.7 * ((e.clientX - d.lx) / d.k / dt) + 0.3 * d.v
    d.lx = e.clientX
    d.lt = e.timeStamp
    const max = (n - 1) * spacing
    let off = d.off - dx
    if (off < 0) off *= 0.35
    if (off > max) off = max + (off - max) * 0.35
    sim.current.off = off
  }
  const onUp = (e: React.PointerEvent) => {
    const d = drag.current
    drag.current = null
    lastTouch.current = performance.now()
    if (!d) return
    if (d.moved) {
      setDragging(false)
      sim.current.vel = -d.v * 1000
      goTo(nearestAt(sim.current.off - d.v * 180, spacing, n))
      return
    }
    const card = (e.target as HTMLElement).closest('[data-i]')
    if (card) goTo(Number(card.getAttribute('data-i')))
  }
  const step = (dir: number) => {
    lastTouch.current = performance.now()
    goTo(clamp(activeRef.current + dir, 0, n - 1))
  }
  const onKey = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowRight') step(1)
    else if (e.key === 'ArrowLeft') step(-1)
    else return
    e.preventDefault()
  }

  const s = slides[active] || {}

  return (
    <div
      ref={rootRef}
      className={['pl-root', className].filter(Boolean).join(' ')}
      style={{
        height,
        ['--pl-bg' as string]: background,
        ['--pl-ink' as string]: ink,
        ['--pl-muted' as string]: 'color-mix(in srgb, var(--pl-ink) 55%, transparent)',
        ['--pl-line' as string]: 'color-mix(in srgb, var(--pl-ink) 18%, transparent)',
        ['--pl-cw' as string]: size.cw + 'px',
        ...style,
      }}
      data-drag={dragging ? '1' : '0'}
      role="region"
      aria-roledescription="carrossel"
      aria-label={ariaLabel}
      tabIndex={0}
      onKeyDown={onKey}
      onPointerDown={onDown}
      onPointerMove={onMove}
      onPointerUp={onUp}
      onPointerCancel={onUp}
    >
      <PolaroidLineStyles />
      <svg className="pl-string" aria-hidden="true">
        <path ref={pathRef} fill="none" stroke={string} strokeWidth="1.5" strokeLinecap="round" />
      </svg>
      {slides.map((sl, i) => (
        <div
          key={i}
          className="pl-card"
          data-i={i}
          data-on={i === active ? '1' : '0'}
          ref={(el) => void (cards.current[i] = el)}
          aria-hidden={i === active ? undefined : true}
        >
          <div className="pl-print">
            <div className="pl-shot">
              {srcs[i] ? (
                <img src={srcs[i]} alt={sl.alt || sl.title || ''} draggable={false} />
              ) : null}
            </div>
            <div className="pl-note">{sl.title || ''}</div>
          </div>
          <div className="pl-peg" />
        </div>
      ))}
      <div className="pl-bar">
        <div className="pl-cap" key={active} aria-hidden="true">
          {s.title ? <span className="pl-title">{s.title}</span> : null}
          {s.caption ? <span className="pl-sub">{s.caption}</span> : null}
        </div>
        <span className="pl-count" aria-hidden="true">
          <b>{pad2(active + 1)}</b> / {pad2(n)}
        </span>
        <button type="button" className="pl-btn" aria-label={L.previous} onClick={() => step(-1)}>
          <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
            <path d="M10 3 5 8l5 5" stroke="currentColor" strokeWidth="1.4" />
          </svg>
        </button>
        <button type="button" className="pl-btn" aria-label={L.next} onClick={() => step(1)}>
          <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
            <path d="m6 3 5 5-5 5" stroke="currentColor" strokeWidth="1.4" />
          </svg>
        </button>
      </div>
      <div className="pl-sr" aria-live="polite">
        {L.status(active + 1, n, s.title)}
      </div>
    </div>
  )
}

