'use client'

import Image from 'next/image'
import Link from 'next/link'
import { useId, useMemo, useState } from 'react'
import { ArrowRight, Search } from 'lucide-react'

import { BlogGrid } from '@/components/library/data-display/BlogGrid'
import { Input } from '@/components/ui/input'
import { cn } from '@/lib/utils'

export type BlogSidebarPost = {
  slug: string
  title: string
  excerpt: string
  image: { src: string; alt: string }
  date: string
  category?: string
  href: string
}

export type BlogSidebarLabels = {
  searchLabel?: string
  searchPlaceholder?: string
  categoriesTitle?: string
  allLabel?: string
  recentTitle?: string
  emptyMessage?: string
}

export type BlogSidebarLayoutProps = {
  posts: BlogSidebarPost[]
  /** Posts recentes exibidos na barra lateral; padrão: os 3 primeiros. */
  recent?: BlogSidebarPost[]
  labels?: BlogSidebarLabels
  cta?: { title: string; description?: string; action: { label: string; href: string } }
  className?: string
}

const normalize = (value: string) =>
  value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()

export function BlogSidebarLayout({
  posts,
  recent = posts.slice(0, 3),
  labels = {},
  cta,
  className,
}: BlogSidebarLayoutProps) {
  const {
    searchLabel = 'Buscar no blog',
    searchPlaceholder = 'Digite um termo',
    categoriesTitle = 'Categorias',
    allLabel = 'Todas',
    recentTitle = 'Posts recentes',
    emptyMessage = 'Nenhum artigo encontrado.',
  } = labels
  const searchId = useId()
  const [query, setQuery] = useState('')
  const [category, setCategory] = useState<string | null>(null)

  const categories = useMemo(() => {
    const counts = new Map<string, number>()
    posts.forEach((post) => {
      if (post.category) counts.set(post.category, (counts.get(post.category) ?? 0) + 1)
    })
    return Array.from(counts, ([name, count]) => ({ name, count }))
  }, [posts])

  const term = normalize(query.trim())
  const visible = posts.filter(
    (post) =>
      (!category || post.category === category) &&
      (!term || normalize([post.title, post.excerpt, post.category].join(' ')).includes(term)),
  )

  const filters = [
    { name: null as string | null, label: allLabel, count: posts.length },
    ...categories.map((item) => ({
      name: item.name as string | null,
      label: item.name,
      count: item.count,
    })),
  ]

  return (
    <section className={cn('py-16 md:py-24', className)} aria-label="Artigos do blog">
      <div className="container grid gap-10 lg:grid-cols-[minmax(0,1fr)_320px] lg:gap-x-12 lg:gap-y-6">
        <div className="space-y-6 lg:col-start-2 lg:row-start-1">
          <div className="rounded-2xl border bg-card p-6 shadow-sm">
            <label htmlFor={searchId} className="text-sm font-semibold">
              {searchLabel}
            </label>
            <div className="relative mt-3">
              <Search
                className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground"
                aria-hidden="true"
              />
              <Input
                id={searchId}
                type="search"
                value={query}
                onChange={(event) => setQuery(event.target.value)}
                placeholder={searchPlaceholder}
                className="pl-9"
              />
            </div>
          </div>

          <nav
            aria-labelledby={`${searchId}-categorias`}
            className="rounded-2xl border bg-card p-6 shadow-sm"
          >
            <h2 id={`${searchId}-categorias`} className="text-sm font-semibold">
              {categoriesTitle}
            </h2>
            <ul className="mt-3 space-y-1">
              {filters.map((filter) => {
                const active = category === filter.name
                return (
                  <li key={filter.label}>
                    <button
                      type="button"
                      aria-pressed={active}
                      onClick={() => setCategory(filter.name)}
                      className={cn(
                        'flex w-full items-center justify-between rounded-lg px-3 py-2 text-left text-sm transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
                        active
                          ? 'bg-primary font-medium text-primary-foreground'
                          : 'text-muted-foreground hover:bg-muted hover:text-foreground',
                      )}
                    >
                      {filter.label}
                      <span
                        className={cn(
                          'rounded-full px-2 py-0.5 text-xs',
                          active ? 'bg-primary-foreground/20' : 'bg-muted',
                        )}
                      >
                        {filter.count}
                      </span>
                    </button>
                  </li>
                )
              })}
            </ul>
          </nav>
        </div>

        <div className="lg:col-start-1 lg:row-span-2 lg:row-start-1">
          <p className="sr-only" aria-live="polite">
            {visible.length} {visible.length === 1 ? 'artigo encontrado' : 'artigos encontrados'}
          </p>
          {visible.length ? (
            <BlogGrid
              posts={visible}
              className="py-0 md:py-0 [&_.container]:max-w-none [&_.container]:px-0 lg:[&_.grid]:grid-cols-2"
            />
          ) : (
            <p className="rounded-2xl border border-dashed p-10 text-center text-muted-foreground">
              {emptyMessage}
            </p>
          )}
        </div>

        <div className="space-y-6 lg:sticky lg:top-28 lg:col-start-2 lg:row-start-2 lg:self-start">
          {recent.length ? (
            <div className="rounded-2xl border bg-card p-6 shadow-sm">
              <h2 className="text-sm font-semibold">{recentTitle}</h2>
              <ul className="mt-4 space-y-4">
                {recent.map((post) => (
                  <li key={post.slug}>
                    <Link
                      href={post.href}
                      className="group flex gap-3 rounded-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    >
                      <span className="relative h-16 w-16 shrink-0 overflow-hidden rounded-lg bg-muted">
                        <Image
                          src={post.image.src}
                          alt=""
                          fill
                          className="object-cover"
                          sizes="64px"
                        />
                      </span>
                      <span className="min-w-0">
                        <span className="line-clamp-2 text-sm font-medium leading-snug group-hover:text-primary">
                          {post.title}
                        </span>
                        <span className="mt-1 block text-xs text-muted-foreground">
                          {post.date}
                        </span>
                      </span>
                    </Link>
                  </li>
                ))}
              </ul>
            </div>
          ) : null}

          {cta ? (
            <div className="rounded-2xl bg-primary p-6 text-primary-foreground shadow-lg shadow-primary/20">
              <h2 className="text-lg font-semibold">{cta.title}</h2>
              {cta.description ? (
                <p className="mt-2 text-sm leading-6 text-primary-foreground/80">
                  {cta.description}
                </p>
              ) : null}
              <Link
                href={cta.action.href}
                className="mt-5 inline-flex items-center gap-2 rounded-lg bg-primary-foreground px-4 py-2 text-sm font-semibold text-primary transition hover:bg-primary-foreground/90"
              >
                {cta.action.label}
                <ArrowRight className="h-4 w-4" aria-hidden="true" />
              </Link>
            </div>
          ) : null}
        </div>
      </div>
    </section>
  )
}

'use client'

import Image from 'next/image'
import { ChevronLeft, ChevronRight } from 'lucide-react'
import { useEffect, useRef, useState } from 'react'
import { useReducedMotion } from '@/components/library/motion/useReducedMotion'
import { cn } from '@/lib/utils'

export type CircularCarouselItem = {
  image: { src: string; alt: string }
  title: string
  description?: string
}

export type CircularCarouselProps = {
  items: CircularCarouselItem[]
  autoplay?: boolean
  interval?: number
  cardWidth?: number
  ariaLabel?: string
  className?: string
}

export function CircularCarousel({
  items,
  autoplay = true,
  interval = 3500,
  cardWidth = 200,
  ariaLabel = 'Carrossel circular',
  className,
}: CircularCarouselProps) {
  const [step, setStep] = useState(0)
  const [paused, setPaused] = useState(false)
  const reduced = useReducedMotion()
  const dragStart = useRef<number | null>(null)

  const count = items.length
  const angle = 360 / Math.max(count, 1)
  const radius = Math.round(cardWidth / 2 / Math.tan(Math.PI / Math.max(count, 3)) + 24)
  const active = ((step % count) + count) % count

  useEffect(() => {
    if (!autoplay || paused || reduced || count < 2) return
    const timer = window.setInterval(() => setStep((value) => value + 1), interval)
    return () => window.clearInterval(timer)
  }, [autoplay, count, interval, paused, reduced])

  if (!count) return null

  const go = (delta: number) => setStep((value) => value + delta)

  return (
    <section
      aria-roledescription="carrossel"
      aria-label={ariaLabel}
      className={cn('relative w-full overflow-hidden py-6', className)}
      onPointerEnter={() => setPaused(true)}
      onPointerLeave={() => {
        setPaused(false)
        dragStart.current = null
      }}
      onFocus={() => setPaused(true)}
      onBlur={() => setPaused(false)}
      onKeyDown={(event) => {
        if (event.key === 'ArrowRight') go(1)
        if (event.key === 'ArrowLeft') go(-1)
      }}
    >
      <div
        className="relative mx-auto flex h-[22rem] cursor-grab touch-pan-y select-none items-center justify-center [perspective:1100px] active:cursor-grabbing"
        onPointerDown={(event) => {
          dragStart.current = event.clientX
        }}
        onPointerUp={(event) => {
          if (dragStart.current === null) return
          const delta = event.clientX - dragStart.current
          if (Math.abs(delta) > 40) go(delta < 0 ? 1 : -1)
          dragStart.current = null
        }}
      >
        <div
          className={cn(
            'relative h-64 [transform-style:preserve-3d]',
            !reduced && 'transition-transform duration-700',
          )}
          style={{
            width: cardWidth,
            transform: `translateZ(${-radius}px) rotateY(${-step * angle}deg)`,
            transitionTimingFunction: 'cubic-bezier(.22,1,.36,1)',
          }}
        >
          {items.map((item, index) => {
            const isActive = index === active
            return (
              <figure
                key={item.title}
                aria-hidden={!isActive}
                className={cn(
                  'absolute inset-0 overflow-hidden rounded-2xl border bg-card shadow-xl transition duration-500 [backface-visibility:hidden]',
                  isActive ? 'opacity-100' : 'opacity-60',
                )}
                style={{ transform: `rotateY(${index * angle}deg) translateZ(${radius}px)` }}
              >
                <Image
                  src={item.image.src}
                  alt={item.image.alt}
                  fill
                  sizes={`${cardWidth}px`}
                  draggable={false}
                  className="object-cover"
                />
                <figcaption className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/75 to-transparent p-4 pt-10 text-sm font-semibold text-white">
                  {item.title}
                </figcaption>
              </figure>
            )
          })}
        </div>
      </div>

      <div className="mx-auto mt-2 flex max-w-md flex-col items-center text-center">
        <div aria-live="polite" className="min-h-14">
          <p className="font-semibold">{items[active].title}</p>
          {items[active].description ? (
            <p className="mt-1 text-sm text-muted-foreground">{items[active].description}</p>
          ) : null}
        </div>
        <div className="mt-3 flex items-center gap-3">
          <button
            type="button"
            onClick={() => go(-1)}
            aria-label="Anterior"
            className="flex h-10 w-10 items-center justify-center rounded-full border bg-background transition hover:border-primary hover:text-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            <ChevronLeft className="h-4 w-4" />
          </button>
          <div className="flex gap-1.5">
            {items.map((item, index) => (
              <button
                type="button"
                key={item.title}
                onClick={() => go(index - active)}
                aria-label={`Ir para ${item.title}`}
                aria-current={index === active}
                className={cn(
                  'h-2 rounded-full transition-all',
                  index === active
                    ? 'w-6 bg-primary'
                    : 'w-2 bg-muted-foreground/30 hover:bg-muted-foreground/60',
                )}
              />
            ))}
          </div>
          <button
            type="button"
            onClick={() => go(1)}
            aria-label="Próximo"
            className="flex h-10 w-10 items-center justify-center rounded-full border bg-background transition hover:border-primary hover:text-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            <ChevronRight className="h-4 w-4" />
          </button>
        </div>
      </div>
    </section>
  )
}

'use client'

import type { ReactNode } from 'react'
import { useMemo, useState } from 'react'
import Link from 'next/link'
import { ArrowRight, Boxes, Search } from 'lucide-react'

import { cn } from '@/lib/utils'

export type ExtensionDirectoryItem = {
  id: string
  name: string
  description: string
  category: string
  href: string
  icon?: ReactNode
  color?: string
}

export type ExtensionDirectorySectionProps = {
  eyebrow?: string
  title: string
  description?: string
  items: readonly ExtensionDirectoryItem[]
  action?: { label: string; href: string }
  className?: string
}

export function ExtensionDirectorySection({
  eyebrow,
  title,
  description,
  items,
  action,
  className,
}: ExtensionDirectorySectionProps) {
  const categories = useMemo(() => Array.from(new Set(items.map((item) => item.category))), [items])
  const [category, setCategory] = useState('all')
  const [query, setQuery] = useState('')
  const visible = useMemo(() => {
    const normalized = query.trim().toLocaleLowerCase('pt-BR')
    return items.filter(
      (item) =>
        (category === 'all' || item.category === category) &&
        (!normalized ||
          `${item.name} ${item.description}`.toLocaleLowerCase('pt-BR').includes(normalized)),
    )
  }, [category, items, query])

  return (
    <section className={cn('bg-[#0d0d0f] py-20 text-white md:py-28', className)}>
      <div className="container">
        <div className="grid gap-8 lg:grid-cols-[.9fr_1.1fr] lg:items-end">
          <div>
            {eyebrow ? <p className="text-sm font-semibold text-[#ff6b63]">{eyebrow}</p> : null}
            <h2 className="mt-5 text-4xl font-bold tracking-[-0.04em] md:text-6xl">{title}</h2>
          </div>
          {description ? (
            <p className="max-w-2xl text-lg leading-8 text-white/50 lg:justify-self-end">
              {description}
            </p>
          ) : null}
        </div>

        <div className="mt-12 flex flex-col gap-5 lg:flex-row lg:items-center lg:justify-between">
          <div className="flex gap-2 overflow-x-auto pb-1">
            {['all', ...categories].map((item) => (
              <button
                key={item}
                type="button"
                aria-pressed={category === item}
                onClick={() => setCategory(item)}
                className={cn(
                  'min-w-fit rounded-full border px-4 py-2 text-xs font-semibold transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#ff6b63]',
                  category === item
                    ? 'border-white bg-white text-black'
                    : 'border-white/15 bg-white/5 text-white/55 hover:text-white',
                )}
              >
                {item === 'all' ? 'Todas' : item}
              </button>
            ))}
          </div>
          <label className="flex min-w-[260px] items-center gap-3 rounded-xl border border-white/15 bg-white/5 px-4 py-3">
            <Search className="h-4 w-4 text-white/35" aria-hidden />
            <span className="sr-only">Buscar extensões</span>
            <input
              type="search"
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder="Buscar extensões..."
              className="min-w-0 flex-1 bg-transparent text-sm outline-none placeholder:text-white/30"
            />
          </label>
        </div>

        <div className="mt-8 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
          {visible.map((item) => (
            <Link
              key={item.id}
              href={item.href}
              className="group flex min-h-[190px] flex-col rounded-2xl border border-white/10 bg-[#17171a] p-5 transition hover:-translate-y-1 hover:border-white/25 hover:bg-[#1d1d21] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#ff6b63]"
            >
              <div className="flex items-start justify-between gap-4">
                <span
                  className="flex h-11 w-11 items-center justify-center rounded-xl text-white"
                  style={{ backgroundColor: item.color ?? '#e5484d' }}
                >
                  {item.icon ?? <Boxes className="h-5 w-5" aria-hidden />}
                </span>
                <span className="text-[10px] font-semibold uppercase tracking-wider text-white/30">
                  {item.category}
                </span>
              </div>
              <h3 className="mt-6 font-semibold">{item.name}</h3>
              <p className="mt-2 text-sm leading-6 text-white/45">{item.description}</p>
            </Link>
          ))}
        </div>

        {!visible.length ? (
          <p className="mt-8 rounded-2xl border border-dashed border-white/15 p-10 text-center text-sm text-white/40">
            Nenhuma extensão encontrada.
          </p>
        ) : null}

        {action ? (
          <div className="mt-10 text-center">
            <Link
              href={action.href}
              className="inline-flex items-center gap-2 rounded-xl bg-white px-5 py-3 text-sm font-semibold text-black transition hover:-translate-y-0.5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#ff6b63]"
            >
              {action.label}
              <ArrowRight className="h-4 w-4" aria-hidden />
            </Link>
          </div>
        ) : null}
      </div>
    </section>
  )
}

import type { LucideIcon } from 'lucide-react'
import { cn } from '@/lib/utils'

export type FeatureGridProps = {
  title?: string
  description?: string
  features: Array<{ title: string; description: string; icon?: LucideIcon }>
  className?: string
}

export function FeatureGrid({ title, description, features, className }: FeatureGridProps) {
  return (
    <section
      className={cn('py-16 md:py-24', className)}
      aria-labelledby={title ? 'features-title' : undefined}
    >
      <div className="container">
        {title ? (
          <h2 id="features-title" className="text-3xl font-bold tracking-tight md:text-4xl">
