import type { ReactNode } from 'react'
import Image from 'next/image'
import Link from 'next/link'
import { ArrowUpRight } from 'lucide-react'

import { cn } from '@/lib/utils'

export type InteractiveCardVariant = 'bordered' | 'elevated' | 'glass' | 'editorial' | 'spotlight'

export type InteractiveCardProps = {
  title: string
  description?: string
  eyebrow?: string
  image?: { src: string; alt: string }
  icon?: ReactNode
  href?: string
  actionLabel?: string
  variant?: InteractiveCardVariant
  className?: string
}

const variants: Record<InteractiveCardVariant, string> = {
  bordered: 'border bg-card hover:border-primary/50',
  elevated: 'border bg-card shadow-md hover:-translate-y-2 hover:shadow-2xl',
  glass:
    'border border-white/20 bg-white/10 text-white shadow-xl backdrop-blur-xl hover:bg-white/15',
  editorial:
    'border-0 bg-slate-950 text-white shadow-xl hover:[&_img]:scale-110 [&_.card-copy]:bg-gradient-to-t [&_.card-copy]:from-black/90 [&_.card-copy]:via-black/30',
  spotlight:
    'border bg-card before:absolute before:-right-16 before:-top-16 before:h-40 before:w-40 before:rounded-full before:bg-primary/15 before:blur-3xl hover:before:bg-primary/30',
}

export function InteractiveCard({
  title,
  description,
  eyebrow,
  image,
  icon,
  href,
  actionLabel = 'Saiba mais',
  variant = 'bordered',
  className,
}: InteractiveCardProps) {
  const content = (
    <>
      {image ? (
        <div
          className={cn(
            'relative aspect-[4/3] overflow-hidden bg-muted',
            variant === 'editorial' && 'absolute inset-0 aspect-auto',
          )}
        >
          <Image
            src={image.src}
            alt={image.alt}
            fill
            className="object-cover transition-transform duration-700"
            sizes="(min-width: 1024px) 33vw, 100vw"
          />
        </div>
      ) : null}

      <div
        className={cn(
          'card-copy relative flex flex-1 flex-col p-6',
          variant === 'editorial' && 'min-h-80 justify-end',
        )}
      >
        {icon ? (
          <span className="mb-6 flex h-11 w-11 items-center justify-center rounded-xl bg-primary/10 text-primary">
            {icon}
          </span>
        ) : null}
        {eyebrow ? (
          <p
            className={cn(
              'text-xs font-bold uppercase tracking-[0.18em] text-primary',
              (variant === 'glass' || variant === 'editorial') && 'text-white/65',
            )}
          >
            {eyebrow}
          </p>
        ) : null}
        <h3 className="mt-2 text-xl font-semibold tracking-tight">{title}</h3>
        {description ? (
          <p
            className={cn(
              'mt-3 text-sm leading-6 text-muted-foreground',
              (variant === 'glass' || variant === 'editorial') && 'text-white/70',
            )}
          >
            {description}
          </p>
        ) : null}
        {href ? (
          <span className="mt-6 inline-flex items-center gap-2 text-sm font-semibold text-primary">
            {actionLabel}
            <ArrowUpRight
              className="h-4 w-4 transition-transform duration-300 group-hover:-translate-y-0.5 group-hover:translate-x-0.5"
              aria-hidden
            />
          </span>
        ) : null}
      </div>
    </>
  )

  const classes = cn(
    'group relative flex h-full min-w-0 flex-col overflow-hidden rounded-3xl transition-all duration-500',
    variants[variant],
    href && 'focus-within:ring-2 focus-within:ring-ring',
    className,
  )

  return href ? (
    <article className={classes}>
      <Link
        href={href}
        className="flex h-full flex-col focus-visible:outline-none"
        aria-label={`${actionLabel}: ${title}`}
      >
        {content}
      </Link>
    </article>
  ) : (
    <article className={classes}>{content}</article>
  )
}

'use client'

import Image from 'next/image'
import { useId, useState } from 'react'
import { AnimatePresence, motion, useReducedMotion } from 'framer-motion'
import { cn } from '@/lib/utils'

export type OfferPackage = {
  id: string
  label: string
  headline: string
  price: string
  priceNote?: string
  description: string
  image?: { src: string; alt: string }
  actions?: Array<{ label: string; href: string; variant?: 'primary' | 'outline' }>
}

export type PackageTabsOfferProps = {
  title?: string
  packages: OfferPackage[]
  className?: string
}

export function PackageTabsOffer({ title, packages, className }: PackageTabsOfferProps) {
  const [activeId, setActiveId] = useState(packages[0]?.id)
  const reduceMotion = useReducedMotion()
  const indicatorId = useId()
  const active = packages.find((item) => item.id === activeId) ?? packages[0]

  if (!active) return null

  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        {title ? (
          <h2 className="mb-8 text-3xl font-bold tracking-tight md:text-4xl">{title}</h2>
        ) : null}
        <div className="overflow-hidden rounded-3xl border bg-card shadow-xl">
          <div className="flex overflow-x-auto border-b" role="tablist">
            {packages.map((item) => {
              const selected = item.id === active.id
              return (
                <button
                  key={item.id}
                  type="button"
                  role="tab"
                  aria-selected={selected}
                  onClick={() => setActiveId(item.id)}
                  className={cn(
                    'relative shrink-0 px-6 py-4 text-sm font-semibold transition',
                    selected ? 'text-primary' : 'text-muted-foreground hover:text-foreground',
                  )}
                >
                  {item.label}
                  {selected ? (
                    <motion.span
                      layoutId={indicatorId}
                      className="absolute inset-x-0 bottom-0 h-0.5 bg-primary"
                    />
                  ) : null}
                </button>
              )
            })}
          </div>

          <AnimatePresence mode="wait">
            <motion.div
              key={active.id}
              role="tabpanel"
              initial={reduceMotion ? false : { opacity: 0, y: 16 }}
              animate={{ opacity: 1, y: 0 }}
              exit={reduceMotion ? undefined : { opacity: 0, y: -16 }}
              transition={{ duration: 0.3 }}
              className={cn(
                'grid gap-8 p-6 md:p-10',
                active.image && 'lg:grid-cols-2 lg:items-center',
              )}
            >
              <div>
                <h3 className="text-lg font-semibold text-muted-foreground">{active.headline}</h3>
                <p className="mt-2 text-5xl font-bold tracking-tight text-primary md:text-6xl">
                  {active.price}
                </p>
                {active.priceNote ? (
                  <p className="mt-1 text-sm text-muted-foreground">{active.priceNote}</p>
                ) : null}
                <p className="mt-6 leading-7 text-muted-foreground">{active.description}</p>
                {active.actions?.length ? (
                  <div className="mt-8 flex flex-wrap gap-3">
                    {active.actions.map((action) => (
                      <a
                        key={action.label}
                        href={action.href}
                        className={cn(
                          'inline-flex rounded-full px-6 py-3 text-sm font-semibold transition',
                          action.variant === 'outline'
                            ? 'border hover:border-primary hover:text-primary'
                            : 'bg-primary text-primary-foreground hover:bg-primary-hover',
                        )}
                      >
                        {action.label}
                      </a>
                    ))}
                  </div>
                ) : null}
              </div>
              {active.image ? (
                <div className="relative aspect-[4/3] overflow-hidden rounded-2xl bg-muted">
                  <Image
                    src={active.image.src}
                    alt={active.image.alt}
                    fill
                    className="object-cover"
                    sizes="(min-width: 1024px) 45vw, 100vw"
                  />
                </div>
              ) : null}
            </motion.div>
          </AnimatePresence>
        </div>
      </div>
    </section>
  )
}

'use client'

import Image from 'next/image'
import { useMemo, useState } from 'react'
import { AnimatePresence, motion, useReducedMotion } from 'framer-motion'
import { ChevronLeft, ChevronRight } from 'lucide-react'
import { cn } from '@/lib/utils'

export type GalleryProject = {
  id: string
  title: string
  category: string
  image: { src: string; alt: string }
  href?: string
}

export type PaginatedProjectGalleryProps = {
  title?: string
  description?: string
  projects: GalleryProject[]
  perPage?: number
  allLabel?: string
  previousLabel?: string
  nextLabel?: string
  className?: string
}

export function PaginatedProjectGallery({
  title,
  description,
  projects,
  perPage = 6,
  allLabel = 'Todos',
  previousLabel = 'Anterior',
  nextLabel = 'Próximo',
  className,
}: PaginatedProjectGalleryProps) {
  const [category, setCategory] = useState<string | null>(null)
  const [page, setPage] = useState(1)
  const reduceMotion = useReducedMotion()
  const categories = useMemo(
    () => Array.from(new Set(projects.map((item) => item.category))),
    [projects],
  )
  const filtered = category ? projects.filter((item) => item.category === category) : projects
  const pages = Math.max(1, Math.ceil(filtered.length / perPage))
  const current = Math.min(page, pages)
  const visible = filtered.slice((current - 1) * perPage, current * perPage)

  function selectCategory(value: string | null) {
    setCategory(value)
    setPage(1)
  }

  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        {title || description ? (
          <div className="mx-auto max-w-2xl text-center">
            {title ? (
              <h2 className="text-3xl font-bold uppercase tracking-tight md:text-4xl">{title}</h2>
            ) : null}
            {description ? (
              <p className="mt-4 text-lg leading-8 text-muted-foreground">{description}</p>
            ) : null}
          </div>
        ) : null}

        <div
          className="mt-10 flex flex-wrap justify-center gap-2"
          role="group"
          aria-label="Filtrar projetos"
        >
          {[null, ...categories].map((item) => (
            <button
              key={item ?? 'all'}
              type="button"
              onClick={() => selectCategory(item)}
              aria-pressed={category === item}
              className={cn(
                'rounded-full border px-4 py-2 text-sm font-medium transition',
                category === item
                  ? 'border-primary bg-primary text-primary-foreground'
                  : 'hover:border-primary/50 hover:text-primary',
              )}
            >
              {item ?? allLabel}
            </button>
          ))}
        </div>

        <motion.ul layout className="mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          <AnimatePresence mode="popLayout">
            {visible.map((project) => (
              <motion.li
                layout
                key={project.id}
                initial={reduceMotion ? false : { opacity: 0, scale: 0.94 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={reduceMotion ? undefined : { opacity: 0, scale: 0.94 }}
                transition={{ duration: 0.3 }}
              >
                <a
                  href={project.href ?? '#'}
                  className="group relative block aspect-[4/3] overflow-hidden rounded-2xl bg-muted"
                >
                  <Image
                    src={project.image.src}
                    alt={project.image.alt}
                    fill
                    className="object-cover transition duration-700 group-hover:scale-110"
                    sizes="(min-width: 1024px) 33vw, (min-width: 640px) 50vw, 100vw"
                  />
                  <span className="absolute inset-0 flex flex-col justify-end bg-gradient-to-t from-primary/90 via-primary/30 to-transparent p-5 text-primary-foreground opacity-0 transition duration-300 group-hover:opacity-100">
                    <span className="translate-y-3 text-xs font-bold uppercase tracking-widest opacity-80 transition duration-300 group-hover:translate-y-0">
                      {project.category}
                    </span>
                    <span className="translate-y-3 text-lg font-semibold transition delay-75 duration-300 group-hover:translate-y-0">
                      {project.title}
                    </span>
                  </span>
                </a>
              </motion.li>
            ))}
          </AnimatePresence>
        </motion.ul>

        {pages > 1 ? (
          <nav className="mt-10 flex items-center justify-center gap-2" aria-label="Paginação">
            <button
              type="button"
              onClick={() => setPage(current - 1)}
              disabled={current === 1}
              className="inline-flex items-center gap-1 rounded-full px-3 py-2 text-sm font-medium transition hover:text-primary disabled:opacity-40"
            >
              <ChevronLeft className="h-4 w-4" />
              {previousLabel}
            </button>
            {Array.from({ length: pages }, (_, index) => index + 1).map((number) => (
              <button
                key={number}
                type="button"
                onClick={() => setPage(number)}
                aria-current={number === current ? 'page' : undefined}
                className={cn(
                  'h-10 w-10 rounded-full text-sm font-semibold transition',
                  number === current ? 'bg-primary text-primary-foreground' : 'hover:bg-muted',
                )}
              >
                {number}
              </button>
            ))}
            <button
              type="button"
              onClick={() => setPage(current + 1)}
              disabled={current === pages}
              className="inline-flex items-center gap-1 rounded-full px-3 py-2 text-sm font-medium transition hover:text-primary disabled:opacity-40"
            >
              {nextLabel}
              <ChevronRight className="h-4 w-4" />
            </button>
          </nav>
        ) : null}
      </div>
    </section>
  )
}

import Link from 'next/link'
import { Check } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type PricingCardsProps = {
