'use client'

import Image from 'next/image'
import Link from 'next/link'
import { ArrowRight, Heart, ShoppingBag, Star } from 'lucide-react'

import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type ProductCardVariant = 'classic' | 'minimal' | 'horizontal' | 'overlay'

export type ProductCardItem = {
  id: string
  name: string
  description?: string
  image: { src: string; alt: string }
  href: string
  price?: string
  previousPrice?: string
  badge?: string
  rating?: number
}

export type ProductCardProps = {
  product: ProductCardItem
  variant?: ProductCardVariant
  actionLabel?: string
  showFavorite?: boolean
  onAddToCart?: (product: ProductCardItem) => void
  onFavorite?: (product: ProductCardItem) => void
  className?: string
}

export function ProductCard({
  product,
  variant = 'classic',
  actionLabel = 'Adicionar',
  showFavorite = false,
  onAddToCart,
  onFavorite,
  className,
}: ProductCardProps) {
  const horizontal = variant === 'horizontal'
  const overlay = variant === 'overlay'

  return (
    <article
      className={cn(
        'group relative flex h-full min-w-0 overflow-hidden rounded-3xl bg-card transition-all duration-500',
        variant === 'classic' && 'flex-col border shadow-sm hover:-translate-y-1 hover:shadow-xl',
        variant === 'minimal' && 'flex-col rounded-none border-0 bg-transparent',
        horizontal && 'min-h-56 flex-row border shadow-sm hover:border-primary/40',
        overlay && 'min-h-[420px] flex-col justify-end bg-slate-950 text-white shadow-xl',
        className,
      )}
    >
      <Link
        href={product.href}
        className={cn(
          'relative block overflow-hidden bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
          horizontal ? 'min-h-full w-2/5 shrink-0' : 'aspect-[4/5] w-full',
          overlay && 'absolute inset-0 aspect-auto',
        )}
        aria-label={`Ver ${product.name}`}
      >
        <Image
          src={product.image.src}
          alt={product.image.alt}
          fill
          className="object-cover transition-transform duration-700 group-hover:scale-105"
          sizes={horizontal ? '(min-width: 768px) 30vw, 45vw' : '(min-width: 1024px) 25vw, 50vw'}
        />
        {overlay ? (
          <span className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/20" />
        ) : null}
      </Link>

      {product.badge ? (
        <span className="absolute left-4 top-4 z-10 rounded-full bg-background/90 px-3 py-1 text-xs font-bold text-foreground shadow-sm backdrop-blur">
          {product.badge}
        </span>
      ) : null}

      {showFavorite ? (
        <button
          type="button"
          onClick={() => onFavorite?.(product)}
          className="absolute right-4 top-4 z-10 flex h-10 w-10 items-center justify-center rounded-full bg-background/90 text-foreground shadow-sm backdrop-blur transition hover:scale-110 hover:text-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          aria-label={`Favoritar ${product.name}`}
        >
          <Heart className="h-4 w-4" aria-hidden />
        </button>
      ) : null}

      <div
        className={cn(
          'relative z-[1] flex flex-1 flex-col p-5',
          horizontal && 'justify-center p-6',
          overlay && 'justify-end p-7',
          variant === 'minimal' && 'px-0',
        )}
      >
        {product.rating ? (
          <div
            className={cn(
              'mb-2 flex items-center gap-1 text-xs text-muted-foreground',
              overlay && 'text-white/70',
            )}
          >
            <Star className="h-3.5 w-3.5 fill-amber-400 text-amber-400" aria-hidden />
            {product.rating.toFixed(1)}
          </div>
        ) : null}

        <Link
          href={product.href}
          className="w-fit rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          <h3 className="text-lg font-semibold tracking-tight transition-colors group-hover:text-primary">
            {product.name}
          </h3>
        </Link>

        {product.description ? (
          <p
            className={cn(
              'mt-2 line-clamp-2 text-sm leading-6 text-muted-foreground',
              overlay && 'text-white/70',
            )}
          >
            {product.description}
          </p>
        ) : null}

        <div className="mt-5 flex items-end justify-between gap-3">
          <div>
            {product.price ? <strong className="text-lg">{product.price}</strong> : null}
            {product.previousPrice ? (
              <span
                className={cn(
                  'ml-2 text-xs text-muted-foreground line-through',
                  overlay && 'text-white/50',
                )}
              >
                {product.previousPrice}
              </span>
            ) : null}
          </div>

          {onAddToCart ? (
            <Button
              type="button"
              size={horizontal ? 'default' : 'icon'}
              variant={overlay ? 'secondary' : 'default'}
              onClick={() => onAddToCart(product)}
              aria-label={`${actionLabel}: ${product.name}`}
              className="shrink-0 gap-2 rounded-full"
            >
              <ShoppingBag className="h-4 w-4" aria-hidden />
              {horizontal ? actionLabel : <span className="sr-only">{actionLabel}</span>}
            </Button>
          ) : (
            <Link
              href={product.href}
              className="inline-flex items-center gap-1 text-sm font-semibold text-primary"
            >
              Ver <ArrowRight className="h-4 w-4" aria-hidden />
            </Link>
          )}
        </div>
      </div>
    </article>
  )
}

'use client'

import { A11y, Autoplay, Keyboard, Navigation, Pagination } from 'swiper/modules'
import { Swiper, SwiperSlide } from 'swiper/react'

import { useReducedMotion } from '@/components/library/motion/useReducedMotion'
import { cn } from '@/lib/utils'

import { ProductCard, type ProductCardItem, type ProductCardVariant } from './ProductCard'

import 'swiper/css'
import 'swiper/css/navigation'
import 'swiper/css/pagination'

export type ProductCarouselProps = {
  products: ProductCardItem[]
  title?: string
  description?: string
  cardVariant?: ProductCardVariant
  slidesPerView?: 2 | 3 | 4
  autoplayDelay?: number | false
  actionLabel?: string
  showFavorite?: boolean
  onAddToCart?: (product: ProductCardItem) => void
  onFavorite?: (product: ProductCardItem) => void
  className?: string
}

export function ProductCarousel({
  products,
  title,
  description,
  cardVariant = 'classic',
  slidesPerView = 4,
  autoplayDelay = false,
  actionLabel,
  showFavorite,
  onAddToCart,
  onFavorite,
  className,
}: ProductCarouselProps) {
  const reducedMotion = useReducedMotion()

  return (
    <section
      className={cn('overflow-hidden py-16 md:py-24', className)}
      aria-labelledby={title ? 'product-carousel-title' : undefined}
    >
      <div className="container">
        {title || description ? (
          <header className="mb-10 max-w-2xl">
            {title ? (
              <h2
                id="product-carousel-title"
                className="text-3xl font-bold tracking-tight md:text-4xl"
              >
                {title}
              </h2>
            ) : null}
            {description ? (
              <p className="mt-3 text-base leading-7 text-muted-foreground">{description}</p>
            ) : null}
          </header>
        ) : null}

        <Swiper
          modules={[A11y, Autoplay, Keyboard, Navigation, Pagination]}
          navigation
          pagination={{ clickable: true, dynamicBullets: true }}
          keyboard={{ enabled: true }}
          autoplay={
            autoplayDelay && !reducedMotion
              ? { delay: autoplayDelay, pauseOnMouseEnter: true, disableOnInteraction: true }
              : false
          }
          spaceBetween={24}
          slidesPerView={1.12}
          breakpoints={{
            640: { slidesPerView: Math.min(2, slidesPerView) },
            1024: { slidesPerView: Math.min(3, slidesPerView) },
            1280: { slidesPerView },
          }}
          className="!overflow-visible !pb-12"
        >
          {products.map((product) => (
            <SwiperSlide key={product.id} className="h-auto">
              <ProductCard
                product={product}
                variant={cardVariant}
                actionLabel={actionLabel}
                showFavorite={showFavorite}
                onAddToCart={onAddToCart}
                onFavorite={onFavorite}
              />
            </SwiperSlide>
          ))}
        </Swiper>
      </div>
    </section>
  )
}

import Image from 'next/image'
import Link from 'next/link'
import { ArrowUpRight } from 'lucide-react'

import { EyebrowHeading } from '@/components/library/primitives/EyebrowHeading'
import {
  getAccentTone,
  padIndex,
  type AccentTone,
} from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

export type ProductCatalogItem = {
  id: string
  title: string
  category: string
  description: string
  href: string
  image: { src: string; alt: string }
  features?: readonly string[]
}

export type ProductCatalogGridProps = {
  products: readonly ProductCatalogItem[]
  title?: string
  eyebrow?: string
  description?: string
  actionLabel?: string
  maxFeatures?: number
  tone?: AccentTone
  className?: string
}

const gridLines: Record<AccentTone, string> = {
  glow: 'border-[#493849] bg-[#493849]',
  industrial: 'border-slate-200 bg-slate-200',
  'industrial-dark': 'border-white/10 bg-white/10',
}

/** Catálogo em grade unida por linhas com imagem, recursos e chamada para cada produto. */
export function ProductCatalogGrid({
  products,
  title,
  eyebrow,
  description,
  actionLabel = 'Ver solução',
  maxFeatures = 3,
  tone = 'glow',
  className,
}: ProductCatalogGridProps) {
  const t = getAccentTone(tone)
  const isGlow = tone === 'glow'

  return (
    <section className={cn(t.section, className)}>
      <div className="container py-14 lg:py-16">
        {title ? (
          <EyebrowHeading
            tone={tone}
            eyebrow={eyebrow}
            title={title}
            description={description}
            layout="split"
            className="mb-10 lg:mb-12"
          />
        ) : null}

        <div
          className={cn(
            'grid grid-cols-1 gap-px border md:grid-cols-2 lg:grid-cols-3',
            gridLines[tone],
          )}
        >
          {products.map((product, index) => (
            <Link
              key={product.id}
              href={product.href}
              className={cn(
                'group flex h-full flex-col transition-colors duration-500',
                t.panel,
                isGlow
                  ? 'hover:bg-[#121212]'
                  : tone === 'industrial'
                    ? 'hover:bg-slate-50'
                    : 'hover:bg-slate-950',
                t.focus,
              )}
            >
              <div className="relative h-52 overflow-hidden sm:h-56">
                <Image
                  src={product.image.src}
                  alt={product.image.alt}
                  fill
                  sizes="(max-width: 768px) 100vw, (max-width: 1024px) 50vw, 33vw"
                  className="object-cover transition-transform duration-700 group-hover:scale-105"
                />
                <div
                  className={cn(
                    'absolute inset-0 bg-gradient-to-t to-transparent',
                    isGlow
                      ? 'from-[#121212]/70 via-[#121212]/10'
                      : 'from-slate-950/70 via-slate-950/10',
                  )}
                  aria-hidden
                />
                <span
                  className={cn(
                    'absolute left-5 top-5 text-[0.65rem] tracking-[0.22em]',
                    isGlow ? 'text-[#ffb0eb]' : 'text-amber-400',
                  )}
                >
                  {padIndex(index)} — {product.category}
                </span>
              </div>

              <div className="flex flex-1 flex-col p-6 sm:p-7">
                <h3
                  className={cn(
                    'text-xl font-semibold tracking-wide',
                    !isGlow && 'uppercase',
                    t.strong,
                  )}
                >
                  {product.title}
                </h3>
                <p className={cn('mt-3 text-sm leading-relaxed', t.body)}>{product.description}</p>

                {product.features?.length ? (
                  <ul className="mt-5 space-y-2">
                    {product.features.slice(0, maxFeatures).map((feature) => (
                      <li key={feature} className={cn('flex items-center gap-2.5 text-sm', t.body)}>
                        <span className={cn('h-1.5 w-1.5 shrink-0', t.line)} aria-hidden />
                        {feature}
                      </li>
                    ))}
                  </ul>
                ) : null}

                <div className="mt-auto flex items-center justify-between pt-6">
                  <span
                    className={cn(
                      'text-sm font-semibold tracking-wide transition-colors duration-500',
                      t.strong,
                      isGlow ? 'group-hover:text-[#ffb0eb]' : 'group-hover:text-amber-600',
                    )}
                  >
                    {actionLabel}
                  </span>
                  <span
                    className={cn(
                      'flex h-9 w-9 items-center justify-center border transition-all duration-500',
                      t.border,
                      t.strong,
                      isGlow
                        ? 'group-hover:border-[#c642a5] group-hover:bg-[#c642a5]'
                        : 'group-hover:border-amber-500 group-hover:bg-amber-500 group-hover:text-slate-950',
                    )}
                    aria-hidden
                  >
                    <ArrowUpRight className="h-4 w-4 transition-transform duration-500 group-hover:rotate-45" />
                  </span>
                </div>
              </div>
            </Link>
          ))}
        </div>
      </div>
    </section>
  )
}

'use client'

import { useId, useState } from 'react'
import { ArrowUpRight, Check } from 'lucide-react'

import { cn } from '@/lib/utils'

export type ProductFeatureTab = {
  id: string
  label: string
  title: string
  description: string
  features?: string[]
  image: { src: string; alt: string }
  action?: { label: string; href: string }
}

export type ProductFeatureTabsProps = {
  eyebrow?: string
  title: string
  items: ProductFeatureTab[]
  initialId?: string
  className?: string
}

export function ProductFeatureTabs({
  eyebrow = 'Soluções',
  title,
  items,
  initialId,
  className,
}: ProductFeatureTabsProps) {
  const instanceId = useId()
  const [activeId, setActiveId] = useState(initialId ?? items[0]?.id)
  const activeItem = items.find((item) => item.id === activeId) ?? items[0]

  if (!activeItem) return null

  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        <header className="mb-9 max-w-3xl">
          <p className="text-sm font-semibold uppercase tracking-[0.18em] text-primary">
            {eyebrow}
          </p>
          <h2 className="mt-3 text-balance text-3xl font-bold tracking-tight md:text-4xl lg:text-5xl">
            {title}
          </h2>
        </header>

        <div
          className="mb-6 flex gap-2 overflow-x-auto pb-2 [scrollbar-width:none] max-sm:flex-wrap [&::-webkit-scrollbar]:hidden"
          role="tablist"
          aria-label={title}
        >
          {items.map((item) => {
            const selected = item.id === activeItem.id
            return (
              <button
                key={item.id}
                id={`${instanceId}-tab-${item.id}`}
                type="button"
                role="tab"
                aria-selected={selected}
                aria-controls={`${instanceId}-panel-${item.id}`}
                tabIndex={selected ? 0 : -1}
                onClick={() => setActiveId(item.id)}
                className={cn(
                  'shrink-0 rounded-full border px-4 py-2 text-sm font-medium transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
                  selected
                    ? 'border-primary bg-primary text-primary-foreground'
                    : 'bg-background text-muted-foreground hover:text-foreground',
                )}
              >
                {item.label}
              </button>
            )
          })}
        </div>

        <div
          id={`${instanceId}-panel-${activeItem.id}`}
          role="tabpanel"
          aria-labelledby={`${instanceId}-tab-${activeItem.id}`}
          className="grid overflow-hidden rounded-[2rem] border bg-card shadow-sm lg:grid-cols-2"
        >
          <div className="flex flex-col justify-center p-7 md:p-10 lg:p-12">
            <h3 className="text-2xl font-semibold md:text-3xl">{activeItem.title}</h3>
            <p className="mt-4 leading-7 text-muted-foreground">{activeItem.description}</p>
            {activeItem.features?.length ? (
