                            )}
                          >
                            {product.title}
                          </p>
                        </div>
                        <ArrowUpRight
                          className={cn(
                            'h-4 w-4 shrink-0 transition-transform duration-300',
                            isActive && 'rotate-45',
                          )}
                          aria-hidden
