                  </AccentButton>
                ) : null}
              </div>
            </div>
          ) : (
            <div className="grid gap-0 lg:min-h-[34rem] lg:grid-cols-12">
              <div
                className={cn(
                  'border lg:col-span-5',
                  isGlow ? 'border-[#493849] bg-[#221d2f]' : 'border-white/10 bg-slate-900/40',
                )}
              >
                <div className={cn('divide-y', isGlow ? 'divide-[#493849]' : 'divide-white/10')}>
                  {products.map((product, index) => {
                    const isActive = product.id === active.id
                    return (
                      <button
                        key={product.id}
                        type="button"
                        {...select(product.id)}
                        aria-pressed={isActive}
                        className={cn(
                          'group flex w-full items-center gap-4 px-5 py-5 text-left transition-colors duration-300 sm:px-6 sm:py-6',
                          isActive
                            ? isGlow
                              ? 'bg-gradient-to-r from-[#c642a5] to-[#7c39cf] text-white'
                              : 'bg-amber-500 text-slate-950'
                            : 'text-white hover:bg-white/5',
                          focusRing,
                        )}
                      >
                        <span
                          className={cn(
                            'text-xs tracking-[0.22em]',
                            isActive ? 'opacity-70' : isGlow ? 'text-[#ffb0eb]' : 'text-amber-500',
                          )}
                        >
                          {padIndex(index)}
                        </span>
                        <span className="min-w-0 flex-1">
                          <span className="block truncate text-base font-semibold tracking-wide sm:text-lg">
                            {product.title}
                          </span>
                          <span
                            className={cn(
                              'mt-0.5 block text-xs uppercase tracking-[0.18em]',
                              isActive ? 'opacity-60' : 'text-slate-500',
                            )}
                          >
                            {product.category}
                          </span>
                        </span>
                        <ArrowUpRight
                          className={cn(
                            'h-4 w-4 shrink-0 transition-transform duration-300',
                            isActive ? 'rotate-45' : 'text-slate-500',
                          )}
                          aria-hidden
                        />
                      </button>
                    )
                  })}
                </div>
              </div>

              <div
                className={cn(
                  'relative min-h-[26rem] overflow-hidden border border-t-0 lg:col-span-7 lg:min-h-full lg:border-l-0 lg:border-t',
                  isGlow ? 'border-[#493849]' : 'border-white/10',
                )}
              >
                {products.map((product) => (
                  <div
                    key={product.id}
                    className={cn(
                      'absolute inset-0 transition-opacity duration-500 ease-out',
                      product.id === active.id ? 'opacity-100' : 'pointer-events-none opacity-0',
                    )}
                    aria-hidden={product.id !== active.id}
                  >
                    <Image
                      src={product.image.src}
                      alt={product.image.alt}
                      fill
                      sizes="(max-width: 1024px) 100vw, 58vw"
                      className={cn(
                        'object-cover transition-transform duration-700 ease-out',
                        product.id === active.id ? 'scale-100' : 'scale-110',
                      )}
                    />
                    <div
                      className={cn(
                        'absolute inset-0 bg-gradient-to-t',
                        isGlow
                          ? 'from-[#121212] via-[#121212]/70 to-[#121212]/25'
                          : 'from-slate-950 via-slate-950/70 to-slate-950/25',
                      )}
                    />
                  </div>
                ))}
                <div className="relative z-10 flex h-full min-h-[26rem] flex-col justify-end p-6 sm:p-8 lg:min-h-full lg:p-10">
                  <p
                    className={cn(
                      'mb-3 text-[0.65rem] font-medium uppercase tracking-[0.28em]',
                      isGlow ? 'text-[#ffb0eb]' : 'text-amber-500',
                    )}
                  >
                    {active.category}
                  </p>
                  <h3
                    className={cn(
                      'text-2xl font-semibold text-white sm:text-3xl lg:text-4xl',
                      !isGlow && 'uppercase tracking-wide',
                    )}
                  >
                    {active.title}
                  </h3>
                  <p className="mt-4 max-w-xl text-sm leading-relaxed text-slate-300 sm:text-base">
                    {active.description}
                  </p>
                  {active.features?.length ? (
                    <ul className="mt-6 grid grid-cols-1 gap-2 sm:grid-cols-2">
                      {active.features.map((feature) => (
                        <li
                          key={feature}
                          className={cn(
                            'flex items-center gap-3 border px-3 py-2.5 text-sm text-slate-200 backdrop-blur-sm',
                            isGlow
                              ? 'rounded-lg border-[#493849] bg-[#121212]/40'
                              : 'border-white/10 bg-slate-950/40',
                          )}
                        >
                          <span
                            className={cn(
                              'h-1.5 w-1.5 shrink-0',
                              isGlow ? 'rounded-full bg-[#c642a5]' : 'bg-amber-500',
                            )}
                            aria-hidden
                          />
                          {feature}
                        </li>
                      ))}
                    </ul>
                  ) : null}
                  <div className="mt-8">
                    <AccentButton href={active.href} tone={headingTone}>
                      {actionLabel}
                    </AccentButton>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </section>
  )
}

'use client'

import type { KeyboardEvent, ReactNode } from 'react'
import { useId, useState } from 'react'
import Link from 'next/link'
import { ArrowRight, Check, Layers3 } from 'lucide-react'

import { cn } from '@/lib/utils'

export type ProductSuiteItem = {
  id: string
  label: string
  title: string
  description: string
  features?: readonly string[]
  action?: { label: string; href: string }
  icon?: ReactNode
  visual?: ReactNode
}

export type ProductSuiteSectionProps = {
  eyebrow?: string
  title: string
  description?: string
  items: readonly ProductSuiteItem[]
  initialItemId?: string
  className?: string
}

export function ProductSuiteSection({
  eyebrow,
  title,
  description,
  items,
  initialItemId,
  className,
}: ProductSuiteSectionProps) {
  const baseId = useId()
  const [activeId, setActiveId] = useState(
    initialItemId && items.some((item) => item.id === initialItemId) ? initialItemId : items[0]?.id,
  )
  const activeIndex = Math.max(
    0,
    items.findIndex((item) => item.id === activeId),
  )
  const activeItem = items[activeIndex]

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return
    event.preventDefault()

    const nextIndex =
      event.key === 'Home'
        ? 0
        : event.key === 'End'
          ? items.length - 1
          : event.key === 'ArrowRight'
            ? (index + 1) % items.length
            : (index - 1 + items.length) % items.length

    setActiveId(items[nextIndex]?.id)
    document.getElementById(`${baseId}-tab-${items[nextIndex]?.id}`)?.focus()
  }

  if (!activeItem) return null

  return (
    <section className={cn('overflow-hidden bg-white py-20 text-[#0a2540] md:py-28', className)}>
      <div className="container">
        <div className="max-w-3xl">
          {eyebrow ? <p className="text-sm font-semibold text-[#635bff]">{eyebrow}</p> : null}
          <h2 className="mt-4 text-4xl font-bold tracking-[-0.035em] md:text-6xl">{title}</h2>
          {description ? (
            <p className="mt-6 max-w-2xl text-lg leading-8 text-[#425466]">{description}</p>
          ) : null}
        </div>

        <div
          role="tablist"
          aria-label={title}
          className="mt-12 flex gap-2 overflow-x-auto border-b border-[#dfe7ef] pb-px"
        >
          {items.map((item, index) => {
            const selected = item.id === activeItem.id
            return (
              <button
                key={item.id}
                id={`${baseId}-tab-${item.id}`}
                type="button"
                role="tab"
                aria-selected={selected}
                aria-controls={`${baseId}-panel-${item.id}`}
                tabIndex={selected ? 0 : -1}
                onClick={() => setActiveId(item.id)}
                onKeyDown={(event) => handleKeyDown(event, index)}
                className={cn(
                  'relative flex min-w-fit items-center gap-2 px-4 py-4 text-sm font-semibold text-[#697386] transition hover:text-[#0a2540] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-[#635bff]',
                  selected && 'text-[#635bff]',
                )}
              >
                {item.icon ? <span aria-hidden>{item.icon}</span> : null}
                {item.label}
                {selected ? (
                  <span className="absolute inset-x-3 bottom-0 h-0.5 rounded-full bg-[#635bff]" />
                ) : null}
              </button>
            )
          })}
        </div>

        <article
          id={`${baseId}-panel-${activeItem.id}`}
          role="tabpanel"
          aria-labelledby={`${baseId}-tab-${activeItem.id}`}
          className="grid min-h-[480px] gap-12 rounded-b-[2rem] bg-[#f6f9fc] p-7 sm:p-10 lg:grid-cols-[.82fr_1.18fr] lg:items-center lg:p-14"
        >
          <div>
            <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-[#635bff] text-white shadow-lg shadow-[#635bff]/25">
              {activeItem.icon ?? <Layers3 className="h-5 w-5" aria-hidden />}
            </span>
            <h3 className="mt-7 text-3xl font-bold tracking-tight md:text-4xl">
              {activeItem.title}
            </h3>
            <p className="mt-5 leading-7 text-[#425466]">{activeItem.description}</p>

            {activeItem.features?.length ? (
              <ul className="mt-7 grid gap-3">
                {activeItem.features.map((feature) => (
                  <li key={feature} className="flex items-center gap-3 text-sm text-[#425466]">
                    <span className="flex h-5 w-5 items-center justify-center rounded-full bg-[#635bff]/10 text-[#635bff]">
                      <Check className="h-3 w-3" aria-hidden />
                    </span>
                    {feature}
                  </li>
                ))}
              </ul>
            ) : null}

            {activeItem.action ? (
              <Link
                href={activeItem.action.href}
                className="mt-8 inline-flex items-center gap-2 rounded-full bg-[#0a2540] px-5 py-3 text-sm font-semibold text-white transition hover:bg-[#1d3b53] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#635bff] focus-visible:ring-offset-2"
              >
                {activeItem.action.label}
                <ArrowRight className="h-4 w-4" aria-hidden />
              </Link>
            ) : null}
          </div>

          <div className="relative min-h-[340px] overflow-hidden rounded-[1.75rem] border border-white bg-white p-5 shadow-[0_30px_80px_-35px_rgba(10,37,64,.45)] sm:p-8">
            {activeItem.visual ?? (
              <div className="flex h-full min-h-[300px] flex-col">
                <div className="flex items-center justify-between">
                  <span className="h-3 w-28 rounded-full bg-[#dfe7ef]" />
                  <span className="h-9 w-24 rounded-full bg-[#635bff]/10" />
                </div>
                <div className="mt-8 grid grid-cols-3 gap-3">
                  {[72, 88, 64].map((value) => (
                    <div key={value} className="rounded-2xl border border-[#e6ebf1] p-4">
                      <span className="block h-2 w-12 rounded bg-[#aab7c4]" />
                      <span
                        className="mt-4 block h-6 rounded bg-[#0a2540]"
                        style={{ width: value }}
                      />
                    </div>
                  ))}
                </div>
                <div className="mt-5 flex flex-1 items-end gap-3 rounded-2xl bg-[#f6f9fc] p-5">
                  {[36, 58, 48, 82, 66, 92, 74, 110].map((height, index) => (
                    <span
                      key={`${height}-${index}`}
                      className="flex-1 rounded-t bg-gradient-to-t from-[#635bff] to-[#80e9ff]"
                      style={{ height }}
                    />
                  ))}
                </div>
              </div>
            )}
          </div>
        </article>
      </div>
    </section>
  )
}

import Image from 'next/image'
import Link from 'next/link'
import { ArrowUpRight } from 'lucide-react'

import { EyebrowHeading } from '@/components/library/primitives/EyebrowHeading'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

export type RelatedProductItem = {
  id: string
  title: string
  category: string
  href: string
  image?: { src: string; alt: string }
}

export type RelatedProductsProps = {
  products: readonly RelatedProductItem[]
  title?: string
  eyebrow?: string
  variant?: 'cards' | 'list'
  tone?: AccentTone
  className?: string
}

const gridLines: Record<AccentTone, string> = {
  glow: 'border-[#493849] bg-[#493849]',
  industrial: 'border-slate-200 bg-slate-200',
  'industrial-dark': 'border-white/10 bg-white/10',
}

/** Produtos relacionados em cards com imagem ou em lista editorial com seta. */
export function RelatedProducts({
  products,
  title,
  eyebrow = 'Continue explorando',
  variant = 'cards',
  tone = 'glow',
  className,
}: RelatedProductsProps) {
  const t = getAccentTone(tone)
  const isGlow = tone === 'glow'

  if (!products.length) return null

  return (
    <section className={cn(t.section, className)}>
      <div className="container py-14 lg:py-16">
        {title ? (
          <EyebrowHeading tone={tone} eyebrow={eyebrow} title={title} className="mb-10 lg:mb-12" />
        ) : (
          <div className="mb-8 flex items-center gap-3">
            <span className={cn('h-px w-8', t.line)} aria-hidden />
            <span className={cn('text-[0.65rem] uppercase tracking-[0.28em]', t.accent)}>
              {eyebrow}
            </span>
          </div>
        )}

        {variant === 'cards' ? (
          <div className={cn('grid grid-cols-1 gap-px border md:grid-cols-3', gridLines[tone])}>
            {products.map((product) => (
              <Link
                key={product.id}
                href={product.href}
                className={cn('group flex flex-col', t.panel, t.focus)}
              >
                {product.image ? (
                  <div className="relative h-48 overflow-hidden">
                    <Image
                      src={product.image.src}
                      alt={product.image.alt}
                      fill
                      sizes="(max-width: 768px) 100vw, 33vw"
                      className="object-cover transition-transform duration-700 group-hover:scale-105"
                    />
                  </div>
                ) : null}
                <div className="p-6">
                  <p className={cn('text-[0.65rem] uppercase tracking-[0.2em]', t.accent)}>
                    {product.category}
                  </p>
                  <h3
                    className={cn(
                      'mt-2 text-lg font-semibold tracking-wide',
                      !isGlow && 'uppercase',
                      t.strong,
                    )}
                  >
                    {product.title}
                  </h3>
                </div>
              </Link>
            ))}
          </div>
        ) : (
          <ul className={cn('divide-y border-y', t.divide, t.border)}>
            {products.map((product) => (
              <li key={product.id}>
                <Link
                  href={product.href}
                  className={cn(
                    'group flex items-center justify-between gap-6 py-6 transition-colors',
                    t.focus,
                  )}
                >
                  <div>
                    <p className={cn('text-[0.65rem] uppercase tracking-[0.2em]', t.accent)}>
                      {product.category}
                    </p>
                    <h3
                      className={cn(
                        'mt-1 text-xl font-semibold tracking-wide transition-colors',
                        !isGlow && 'uppercase',
                        t.strong,
                        isGlow ? 'group-hover:text-[#ffb0eb]' : 'group-hover:text-amber-600',
                      )}
                    >
                      {product.title}
                    </h3>
                  </div>
                  <ArrowUpRight
                    className={cn(
                      'h-5 w-5 shrink-0 transition-transform group-hover:rotate-45',
                      t.muted,
                    )}
                    aria-hidden
                  />
                </Link>
              </li>
            ))}
          </ul>
        )}
      </div>
    </section>
  )
}

'use client'

import Image from 'next/image'
import Link from 'next/link'
import { ArrowUpRight } from 'lucide-react'
import { A11y, Autoplay, Keyboard, Navigation } from 'swiper/modules'
import { Swiper, SwiperSlide } from 'swiper/react'

import { useReducedMotion } from '@/components/library/motion/useReducedMotion'
import { cn } from '@/lib/utils'

import 'swiper/css'
import 'swiper/css/navigation'

export type ServiceCarouselItem = {
  id: string
  title: string
  description: string
  href: string
  image?: { src: string; alt: string }
  icon?: React.ReactNode
}

export type ServicesCarouselSectionProps = {
  eyebrow?: string
  title: string
  description?: string
  items: readonly ServiceCarouselItem[]
  action?: { label: string; href: string }
  autoplayDelay?: number | false
  className?: string
}

export function ServicesCarouselSection({
  eyebrow,
  title,
  description,
  items,
  action,
  autoplayDelay = false,
  className,
}: ServicesCarouselSectionProps) {
  const reducedMotion = useReducedMotion()

  return (
    <section className={cn('overflow-hidden bg-[#f4f0f6] py-20 md:py-28', className)}>
      <div className="container">
        <header className="flex flex-col gap-7 lg:flex-row lg:items-end lg:justify-between">
          <div className="max-w-3xl">
            {eyebrow ? (
              <p className="text-xs font-bold uppercase tracking-[0.24em] text-[#752871]">
                {eyebrow}
              </p>
            ) : null}
            <h2 className="mt-4 text-3xl font-bold tracking-tight text-[#10100e] md:text-5xl">
              {title}
            </h2>
            {description ? (
              <p className="mt-5 max-w-2xl leading-7 text-[#5a5560]">{description}</p>
            ) : null}
          </div>
          {action ? (
            <Link
              href={action.href}
              className="inline-flex w-fit items-center gap-2 rounded-full border border-[#752871]/20 bg-white px-5 py-3 text-sm font-semibold text-[#752871] transition hover:border-[#752871]/40 hover:shadow-md"
            >
              {action.label}
              <ArrowUpRight className="h-4 w-4" aria-hidden />
            </Link>
          ) : null}
        </header>

        <Swiper
          modules={[A11y, Autoplay, Keyboard, Navigation]}
          navigation
          keyboard={{ enabled: true }}
          autoplay={
            autoplayDelay && !reducedMotion
              ? { delay: autoplayDelay, pauseOnMouseEnter: true, disableOnInteraction: true }
              : false
          }
          spaceBetween={20}
          slidesPerView={1.08}
          breakpoints={{
            640: { slidesPerView: 2 },
            1024: { slidesPerView: 3 },
            1280: { slidesPerView: 3.4 },
          }}
          className="mt-12 !overflow-visible !pb-3"
        >
          {items.map((item, index) => (
            <SwiperSlide key={item.id} className="h-auto">
              <article className="group flex h-full min-h-[480px] flex-col overflow-hidden rounded-[2rem] border border-[#752871]/10 bg-white p-6 shadow-sm transition duration-300 hover:-translate-y-1 hover:shadow-xl">
                <div className="flex items-start justify-between gap-4">
                  <span className="text-xs font-bold tracking-[0.2em] text-[#752871]">
                    {String(index + 1).padStart(2, '0')}/{String(items.length).padStart(2, '0')}
                  </span>
                  {item.icon ? (
                    <span className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[#752871]/10 text-[#752871]">
                      {item.icon}
                    </span>
                  ) : null}
                </div>

                {item.image ? (
                  <div className="relative mt-7 aspect-[16/10] overflow-hidden rounded-2xl bg-[#ede8ef]">
                    <Image
                      src={item.image.src}
                      alt={item.image.alt}
                      fill
                      className="object-cover transition-transform duration-700 group-hover:scale-105"
                      sizes="(min-width: 1024px) 30vw, 80vw"
                    />
                  </div>
                ) : (
                  <div className="relative mt-7 aspect-[16/10] overflow-hidden rounded-2xl bg-[#3f2644]">
                    <span className="absolute -bottom-12 -right-8 h-44 w-44 rounded-full bg-[#752871]" />
                    <span className="absolute -left-8 top-8 h-32 w-32 rounded-[40%_60%] bg-[#9b4b96]" />
                  </div>
                )}

                <h3 className="mt-7 text-2xl font-semibold text-[#10100e]">{item.title}</h3>
                <p className="mt-3 line-clamp-3 text-sm leading-6 text-[#5a5560]">
                  {item.description}
                </p>
                <Link
                  href={item.href}
                  className="mt-auto inline-flex items-center gap-2 pt-6 text-sm font-semibold text-[#752871]"
                >
                  Leia mais
                  <ArrowUpRight
                    className="h-4 w-4 transition-transform group-hover:-translate-y-0.5 group-hover:translate-x-0.5"
                    aria-hidden
                  />
                </Link>
              </article>
            </SwiperSlide>
          ))}
        </Swiper>
      </div>
    </section>
  )
}

'use client'

import type { ReactNode } from 'react'
import { useMemo, useState } from 'react'
import Link from 'next/link'
