export type NumberedAccordionItem = {
  title: string
  description: string
}

export type NumberedAccordionProps = {
  items: readonly NumberedAccordionItem[]
  defaultOpenIndex?: number | null
  tone?: AccentTone
  className?: string
}

/** Lista de especificações numeradas em acordeão, com um item aberto por vez. */
export function NumberedAccordion({
  items,
  defaultOpenIndex = 0,
  tone = 'glow',
  className,
}: NumberedAccordionProps) {
  const t = getAccentTone(tone)
  const baseId = useId()
  const [active, setActive] = useState<number | null>(defaultOpenIndex)

  return (
    <div className={cn('divide-y border-y', t.divide, t.border, className)}>
      {items.map((item, index) => {
        const isOpen = active === index
        const panelId = `${baseId}-${index}`
        return (
          <div key={item.title}>
            <button
              type="button"
              onClick={() => setActive(isOpen ? null : index)}
              className={cn(
                'flex w-full items-center justify-between gap-6 py-5 text-left transition-colors',
                t.panelHover,
                t.focus,
              )}
              aria-expanded={isOpen}
              aria-controls={panelId}
            >
              <span className="flex items-start gap-4 sm:items-center">
                <span className={cn('text-xs tracking-[0.2em]', t.accent)}>{padIndex(index)}</span>
                <span className={cn('text-base font-medium', t.strong)}>{item.title}</span>
              </span>
              <ChevronDown
                className={cn(
                  'h-4 w-4 shrink-0 transition-transform duration-300',
                  isOpen ? cn('rotate-180', t.accent) : t.muted,
                )}
                aria-hidden
              />
            </button>
            <div
              id={panelId}
              className={cn(
                'grid transition-all duration-500 ease-out',
                isOpen ? 'grid-rows-[1fr] opacity-100' : 'grid-rows-[0fr] opacity-0',
              )}
            >
              <div className="overflow-hidden" aria-hidden={!isOpen}>
                <p
                  className={cn('pb-5 ps-10 text-sm leading-relaxed sm:ps-12 sm:text-base', t.body)}
                >
                  {item.description}
                </p>
              </div>
            </div>
          </div>
        )
      })}
    </div>
  )
}

import type { HTMLAttributes, ReactNode } from 'react'
import { Check } from 'lucide-react'
import { cn } from '@/lib/utils'

export type ProgressStep = {
  label: string
  description?: string
  icon?: ReactNode
}

export interface ProgressStepsProps extends Omit<HTMLAttributes<HTMLOListElement>, 'children'> {
  steps: readonly ProgressStep[]
  currentStep: number
  orientation?: 'horizontal' | 'vertical'
  variant?: 'numbered' | 'compact'
  label?: string
}

export function ProgressSteps({
  steps,
  currentStep,
  orientation = 'horizontal',
  variant = 'numbered',
  label = 'Progresso',
  className,
  ...props
}: ProgressStepsProps) {
  return (
    <ol
      aria-label={label}
      className={cn(
        'flex',
        orientation === 'horizontal'
          ? 'w-full flex-col gap-4 sm:flex-row sm:gap-0'
          : 'flex-col gap-0',
        className,
      )}
      {...props}
    >
      {steps.map((step, index) => {
        const position = index + 1
        const completed = position < currentStep
        const current = position === currentStep
        return (
          <li
            key={`${step.label}-${index}`}
            aria-current={current ? 'step' : undefined}
            className={cn(
              'relative flex min-w-0',
              orientation === 'horizontal' ? 'flex-1 items-start' : 'min-h-20',
            )}
          >
            {index < steps.length - 1 ? (
              <span
                aria-hidden="true"
                className={cn(
                  'absolute bg-border',
                  orientation === 'horizontal'
                    ? 'left-5 top-5 hidden h-px w-[calc(100%-2.5rem)] sm:block'
                    : 'bottom-0 left-5 top-10 w-px',
                  completed && 'bg-primary',
                )}
              />
            ) : null}
            <div
              className={cn(
                'relative z-10 flex min-w-0',
                orientation === 'horizontal'
                  ? 'w-full flex-col items-center text-center sm:pr-4'
                  : 'items-start gap-4',
              )}
            >
              <span
                className={cn(
                  'flex h-10 w-10 shrink-0 items-center justify-center rounded-full border-2 bg-background text-sm font-semibold transition-colors',
                  completed && 'border-primary bg-primary text-primary-foreground',
                  current && 'border-primary text-primary ring-4 ring-primary/10',
                )}
              >
                {completed ? (
                  <Check className="h-5 w-5" aria-label="Concluído" />
                ) : (
                  (step.icon ?? (variant === 'numbered' ? position : null))
                )}
              </span>
              <div className={cn(orientation === 'horizontal' && 'mt-3')}>
                <span
                  className={cn(
                    'block font-medium',
                    !completed && !current && 'text-muted-foreground',
                  )}
                >
                  {step.label}
                </span>
                {step.description && variant !== 'compact' ? (
                  <span className="mt-1 block text-sm text-muted-foreground">
                    {step.description}
                  </span>
                ) : null}
              </div>
            </div>
          </li>
        )
      })}
    </ol>
  )
}

'use client'

import { useEffect, useId, useRef, type ReactNode } from 'react'
import { X } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type SheetPanelProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  title: string
  description?: string
  children: ReactNode
  side?: 'left' | 'right'
  className?: string
}

export function SheetPanel({
  open,
  onOpenChange,
  title,
  description,
  children,
  side = 'right',
  className,
}: SheetPanelProps) {
  const titleId = useId()
  const descriptionId = useId()
  const panelRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (!open) return
    const previousFocus = document.activeElement as HTMLElement | null
    panelRef.current?.focus()
    function onKeyDown(event: KeyboardEvent) {
      if (event.key === 'Escape') onOpenChange(false)
      if (event.key === 'Tab' && panelRef.current) {
        const focusable = Array.from(
          panelRef.current.querySelectorAll<HTMLElement>(
            'button, a, input, select, textarea, [tabindex]:not([tabindex="-1"])',
          ),
        )
        if (!focusable.length) return
        const first = focusable[0]
        const last = focusable[focusable.length - 1]
        if (event.shiftKey && document.activeElement === first) {
          event.preventDefault()
          last.focus()
        } else if (!event.shiftKey && document.activeElement === last) {
          event.preventDefault()
          first.focus()
        }
      }
    }
    document.addEventListener('keydown', onKeyDown)
    return () => {
      document.removeEventListener('keydown', onKeyDown)
      previousFocus?.focus()
    }
  }, [open, onOpenChange])

  if (!open) return null
  return (
    <div className="fixed inset-0 z-50">
      <button
        type="button"
        className="absolute inset-0 bg-black/60"
        onClick={() => onOpenChange(false)}
        aria-label="Fechar painel"
      />
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        aria-describedby={description ? descriptionId : undefined}
        tabIndex={-1}
        className={cn(
          'absolute inset-y-0 w-full max-w-md overflow-y-auto bg-background p-6 shadow-xl outline-none',
          side === 'right' ? 'right-0' : 'left-0',
          className,
        )}
      >
        <Button
          type="button"
          size="icon"
          variant="ghost"
          onClick={() => onOpenChange(false)}
          className="absolute right-4 top-4"
          aria-label="Fechar"
        >
          <X className="h-5 w-5" />
        </Button>
        <div className="pr-10">
          <h2 id={titleId} className="text-xl font-semibold">
            {title}
          </h2>
          {description ? (
            <p id={descriptionId} className="mt-2 text-sm text-muted-foreground">
              {description}
            </p>
          ) : null}
        </div>
        <div className="mt-6">{children}</div>
      </div>
    </div>
  )
}

