  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const data = new FormData(event.currentTarget)
    const lines = [
      ...fields.map((field) => `*${field.label}:* ${data.get(field.name) ?? ''}`),
      `*Mensagem:* ${data.get('mensagem') ?? ''}`,
