export function AgencyHeroSection({
  eyebrow,
  title,
  highlightedText,
  description,
  image,
  primaryAction,
  secondaryAction,
  highlights = [],
  className,
}: AgencyHeroSectionProps) {
  return (
    <section
      className={cn(
        'relative isolate overflow-hidden bg-[#faf8fb] py-20 text-[#10100e] md:py-28 lg:py-32',
