        </div>

        <div className="relative mx-auto mt-16 max-w-3xl">
          <div className="absolute -inset-8 -z-10 rounded-full bg-[#ff4f47]/15 blur-3xl" />
          <div className="overflow-hidden rounded-2xl border border-white/15 bg-[#151518]/95 shadow-[0_40px_100px_-30px_rgba(0,0,0,.9)] backdrop-blur-xl">
            <label className="flex items-center gap-3 border-b border-white/10 px-5 py-4">
              <Search className="h-5 w-5 text-white/35" aria-hidden />
              <span className="sr-only">Buscar comandos</span>
              <input
                type="search"
                value={query}
                onChange={(event) => setQuery(event.target.value)}
                placeholder={searchPlaceholder}
                className="min-w-0 flex-1 bg-transparent text-sm text-white outline-none placeholder:text-white/30"
              />
              <kbd className="rounded-md border border-white/15 bg-white/5 px-2 py-1 text-[10px] text-white/45">
                esc
              </kbd>
            </label>

            <div className="p-2">
              {visibleCommands.length ? (
                visibleCommands.map((command, index) => (
                  <button
                    key={command.id}
                    type="button"
                    className={cn(
                      'flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#ff6b63]',
                      index === 0 ? 'bg-white/10' : 'hover:bg-white/5',
                    )}
                  >
                    <span className="flex h-9 w-9 items-center justify-center rounded-lg bg-gradient-to-br from-[#ff6b63] to-[#7c4dff] text-white">
                      {command.icon ?? <Sparkles className="h-4 w-4" aria-hidden />}
                    </span>
                    <span className="min-w-0 flex-1">
                      <span className="block truncate text-sm font-medium">{command.label}</span>
                      {command.category ? (
                        <span className="mt-0.5 block text-xs text-white/35">
                          {command.category}
                        </span>
                      ) : null}
                    </span>
                    {command.shortcut ? (
                      <kbd className="rounded-md bg-white/5 px-2 py-1 text-[10px] text-white/45">
                        {command.shortcut}
                      </kbd>
                    ) : null}
                  </button>
                ))
              ) : (
                <p className="px-4 py-10 text-center text-sm text-white/40">
                  Nenhum comando encontrado.
                </p>
              )}
            </div>

            <div className="flex items-center justify-between border-t border-white/10 px-5 py-3 text-[10px] text-white/30">
              <span className="flex items-center gap-1.5">
                <Command className="h-3 w-3" aria-hidden />
                Atalho global
              </span>
              <span>↑↓ navegar · ↵ abrir</span>
            </div>
          </div>
        </div>
      </div>
    </section>
  )
}

'use client'

import Image from 'next/image'
import { motion } from 'framer-motion'

import { AccentButton } from '@/components/library/primitives/AccentButton'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { useReducedMotion } from '@/components/library/motion/useReducedMotion'
import { cn } from '@/lib/utils'

export type FloatingIllustrationHeroProps = {
  title: string
  description?: string
  illustration: { src: string; alt: string; width?: number; height?: number }
  actions?: readonly { label: string; href: string }[]
  tone?: AccentTone
  className?: string
}

/** Hero dividido com título em gradiente animado e ilustração flutuante. */
export function FloatingIllustrationHero({
  title,
  description,
  illustration,
  actions = [],
  tone = 'glow',
  className,
}: FloatingIllustrationHeroProps) {
  const t = getAccentTone(tone)
  const reduced = useReducedMotion()
  const isGlow = tone === 'glow'

  return (
    <section className={cn('overflow-hidden', t.section, className)}>
      <div className="container">
        <div className="flex min-h-[80vh] flex-col items-center justify-between gap-10 py-12 lg:flex-row">
          <motion.div
            initial={reduced ? false : { opacity: 0, x: -40 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.8, ease: 'easeOut' }}
            className="flex flex-1 basis-[300px] flex-col items-center justify-center gap-5 text-center lg:items-start lg:text-left"
          >
            <motion.h1
              className={cn(
                'text-[clamp(2rem,5vw,3.5rem)] font-semibold leading-[1.3]',
                isGlow
                  ? 'bg-[linear-gradient(90deg,#c642a5,#ffb0eb,#7c39cf,#ae89ff,#c642a5)] bg-[length:200%] bg-clip-text text-transparent'
                  : cn(t.heading, 'leading-[1.15]'),
              )}
              animate={
                isGlow && !reduced ? { backgroundPosition: ['0% 50%', '400% 50%'] } : undefined
              }
              transition={{ duration: 4, ease: 'linear', repeat: Infinity }}
            >
              {title}
            </motion.h1>
            {description ? (
              <p className={cn('m-0 max-w-xl text-balance text-xl', t.body)}>{description}</p>
            ) : null}
            {actions.length ? (
              <div className="flex flex-wrap justify-center gap-4 lg:justify-start">
                {actions.map((action) => (
                  <AccentButton key={action.href + action.label} href={action.href} tone={tone}>
                    {action.label}
                  </AccentButton>
                ))}
              </div>
            ) : null}
          </motion.div>

          <motion.div
            initial={reduced ? false : { opacity: 0, x: 40 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.8, delay: 0.2, ease: 'easeOut' }}
            className="flex flex-1 basis-[300px] items-center justify-center"
          >
            <motion.div
              animate={reduced ? undefined : { y: [0, -10, 0] }}
              transition={{ duration: 3, ease: 'easeInOut', repeat: Infinity }}
              className="w-full max-w-xl"
            >
              <Image
                src={illustration.src}
                alt={illustration.alt}
                width={illustration.width ?? 640}
                height={illustration.height ?? 520}
                priority
                className="h-auto w-full"
              />
            </motion.div>
          </motion.div>
        </div>
      </div>
    </section>
  )
}

'use client'

import Image from 'next/image'
import Link from 'next/link'
import { Pause, Play } from 'lucide-react'
import { useState } from 'react'
import { A11y, Autoplay, Keyboard, Navigation, Pagination } from 'swiper/modules'
import { Swiper, SwiperSlide } from 'swiper/react'
import type { Swiper as SwiperInstance } from 'swiper'
import { Button } from '@/components/ui/button'
import { useReducedMotion } from '@/components/library/motion/useReducedMotion'
import { cn } from '@/lib/utils'
import 'swiper/css'
import 'swiper/css/navigation'
import 'swiper/css/pagination'

export type HeroCarouselSlide = {
  id: string
  title: string
  description?: string
  image: { src: string; alt: string }
  action?: { label: string; href: string }
}

export type HeroCarouselProps = {
  slides: HeroCarouselSlide[]
  autoplayDelay?: number | false
  className?: string
  label?: string
}

export function HeroCarousel({
  slides,
  autoplayDelay = 6000,
  className,
  label = 'Destaques',
}: HeroCarouselProps) {
  const reducedMotion = useReducedMotion()
  const [swiper, setSwiper] = useState<SwiperInstance | null>(null)
  const [paused, setPaused] = useState(false)
  const canAutoplay = Boolean(autoplayDelay) && !reducedMotion

  function toggleAutoplay() {
    if (!swiper) return
    if (paused) swiper.autoplay.start()
    else swiper.autoplay.stop()
    setPaused((current) => !current)
  }

  return (
    <section className={cn('relative bg-slate-950 text-white', className)} aria-label={label}>
      <Swiper
        modules={[A11y, Autoplay, Keyboard, Navigation, Pagination]}
        navigation
        pagination={{ clickable: true }}
        keyboard={{ enabled: true }}
        autoplay={
          canAutoplay
            ? { delay: Number(autoplayDelay), disableOnInteraction: true, pauseOnMouseEnter: true }
            : false
        }
        loop={slides.length > 1}
        a11y={{ enabled: true }}
        onSwiper={setSwiper}
        className="min-h-[560px]"
      >
        {slides.map((slide, index) => (
          <SwiperSlide key={slide.id}>
            <article className="relative flex min-h-[560px] items-center">
              <Image
                src={slide.image.src}
                alt={slide.image.alt}
                fill
                priority={index === 0}
                className="object-cover opacity-50"
                sizes="100vw"
              />
              <div className="absolute inset-0 bg-gradient-to-r from-black/80 via-black/45 to-transparent" />
              <div className="container relative z-10 py-20">
                <h2 className="max-w-3xl text-4xl font-bold tracking-tight sm:text-6xl">
                  {slide.title}
                </h2>
                {slide.description ? (
                  <p className="mt-5 max-w-2xl text-lg text-white/80">{slide.description}</p>
                ) : null}
                {slide.action ? (
                  <Button asChild size="lg" className="mt-8">
                    <Link href={slide.action.href}>{slide.action.label}</Link>
                  </Button>
                ) : null}
              </div>
            </article>
          </SwiperSlide>
        ))}
      </Swiper>
      {canAutoplay ? (
        <Button
          type="button"
          size="icon"
          variant="secondary"
          className="absolute bottom-5 right-5 z-20 rounded-full shadow-lg"
          onClick={toggleAutoplay}
          aria-label={paused ? 'Retomar carrossel' : 'Pausar carrossel'}
        >
          {paused ? <Play className="h-4 w-4" /> : <Pause className="h-4 w-4" />}
        </Button>
      ) : null}
    </section>
  )
}

import Image from 'next/image'
import Link from 'next/link'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type HeroImageProps = {
