import { Fragment } from 'react'
import Image from 'next/image'
import Link from 'next/link'

import { AccentButton } from '@/components/library/primitives/AccentButton'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

export type ImageOverlayHeroProps = {
  title: string
  image: { src: string; alt: string }
  eyebrow?: string
  description?: string
  breadcrumbs?: readonly { label: string; href?: string }[]
  actions?: readonly { label: string; href: string }[]
  align?: 'center' | 'left'
  height?: 'md' | 'lg'
  tone?: AccentTone
  className?: string
}

const heights = {
  md: 'min-h-[52svh] md:min-h-[58svh]',
  lg: 'min-h-[70svh] md:min-h-[78svh]',
}

/** Hero de página interna com imagem de fundo, camadas de gradiente e breadcrumb opcional. */
export function ImageOverlayHero({
  title,
  image,
  eyebrow,
  description,
  breadcrumbs = [],
  actions = [],
  align = 'center',
  height = 'md',
  tone = 'glow',
  className,
}: ImageOverlayHeroProps) {
  const t = getAccentTone(tone)
  const isGlow = tone === 'glow'
  const centered = align === 'center'
  const line = <span className={cn('h-px w-8', t.line)} aria-hidden />

  return (
    <section
      className={cn(
        'relative flex items-center overflow-hidden',
        heights[height],
        isGlow ? 'bg-[#0e0e0e]' : 'bg-slate-950',
        className,
      )}
    >
      <Image src={image.src} alt={image.alt} fill priority sizes="100vw" className="object-cover" />
      <div
        className={cn(
          'absolute inset-0 bg-gradient-to-r',
          isGlow
            ? 'from-[#121212]/90 via-[#121212]/65 to-[#121212]/30'
            : 'from-slate-950/90 via-slate-950/60 to-slate-950/30',
        )}
        aria-hidden
      />
      <div
        className={cn(
          'absolute inset-0 bg-gradient-to-t via-transparent',
          isGlow ? 'from-[#121212]/70 to-[#121212]/25' : 'from-slate-950/70 to-slate-950/25',
        )}
        aria-hidden
      />

      <div className="container relative z-10 py-20 md:py-24">
        <div className={cn('max-w-3xl text-white', centered && 'mx-auto text-center')}>
          {breadcrumbs.length ? (
            <nav aria-label="Breadcrumb" className="mb-5">
              <ol
                className={cn(
                  'flex flex-wrap items-center gap-2 text-sm',
                  isGlow ? 'text-[#c1c1c1]' : 'text-slate-300',
                  centered && 'justify-center',
                )}
              >
                {breadcrumbs.map((crumb, index) => (
                  <Fragment key={`${crumb.label}-${index}`}>
                    {index > 0 ? <li aria-hidden>/</li> : null}
                    <li>
                      {crumb.href ? (
                        <Link
                          href={crumb.href}
                          className={cn(
                            'transition-colors',
                            isGlow ? 'hover:text-[#ffb0eb]' : 'hover:text-amber-500',
                          )}
                        >
                          {crumb.label}
                        </Link>
                      ) : (
                        <span className="text-white" aria-current="page">
                          {crumb.label}
                        </span>
                      )}
                    </li>
                  </Fragment>
                ))}
              </ol>
            </nav>
          ) : null}

          {eyebrow ? (
            <div className={cn('mb-5 flex items-center gap-3', centered && 'justify-center')}>
              {line}
              <span
                className={cn(
                  'text-[0.65rem] font-medium uppercase tracking-[0.28em]',
                  isGlow ? 'text-[#ffb0eb]' : 'text-amber-500',
                )}
              >
                {eyebrow}
              </span>
              {centered ? line : null}
            </div>
          ) : null}

          <h1
            className={cn(
              'text-3xl font-semibold leading-[1.12] sm:text-4xl md:text-5xl lg:text-[3.25rem]',
              isGlow ? cn(t.heading, centered && 'mx-auto') : 'uppercase tracking-wide text-white',
            )}
          >
            {title}
          </h1>

          {description ? (
            <p
              className={cn(
                'mt-5 max-w-2xl text-base leading-relaxed md:text-lg',
                isGlow ? 'text-[#c1c1c1]' : 'text-slate-300',
                centered && 'mx-auto',
              )}
            >
              {description}
            </p>
          ) : null}

          {actions.length ? (
            <div className={cn('mt-8 flex flex-wrap gap-3', centered && 'justify-center')}>
              {actions.map((action) => (
                <AccentButton
                  key={action.href + action.label}
                  href={action.href}
                  tone={isGlow ? 'glow' : 'industrial-dark'}
                >
                  {action.label}
                </AccentButton>
              ))}
            </div>
          ) : null}
        </div>
      </div>
    </section>
  )
}

'use client'

import Image from 'next/image'
import Link from 'next/link'
import { useState, type CSSProperties } from 'react'
import { ArrowDown, ArrowRight, ChevronLeft, ChevronRight } from 'lucide-react'
import { A11y, Autoplay, EffectFade, Keyboard, Pagination } from 'swiper/modules'
import { Swiper, SwiperSlide } from 'swiper/react'
import type { Swiper as SwiperInstance } from 'swiper'

import { useReducedMotion } from '@/components/library/motion/useReducedMotion'
import { cn } from '@/lib/utils'

import 'swiper/css'
import 'swiper/css/effect-fade'
import 'swiper/css/pagination'

export type InvestmentHeroSlide = {
  id: string
  eyebrow?: string
  title: string
  subtitle?: string
  description?: string
  image: { src: string; alt: string }
  action?: { label: string; href: string }
}

export type InvestmentHeroCarouselProps = {
  slides: readonly InvestmentHeroSlide[]
  autoplayDelay?: number | false
  scrollLabel?: string | null
  /** Largura/altura do banner. A partir de lg a altura segue a proporção para não cortar a imagem. */
  aspectRatio?: number
  overlay?: boolean
  arrows?: { previous: string; next: string }
  className?: string
}

export function InvestmentHeroCarousel({
  slides,
  autoplayDelay = 6500,
  scrollLabel = 'Explorar conteúdo',
  aspectRatio,
  overlay = true,
  arrows,
  className,
}: InvestmentHeroCarouselProps) {
  const reducedMotion = useReducedMotion()
  const [swiper, setSwiper] = useState<SwiperInstance | null>(null)

  if (!slides.length) return null

  const height = aspectRatio
    ? 'min-h-[640px] md:min-h-[88vh] lg:h-full lg:min-h-0'
    : 'min-h-[640px] md:min-h-[88vh]'
  const arrowClass =
    'flex h-9 w-9 items-center justify-center rounded-full border border-white/60 text-white transition hover:bg-white/15 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white'

  return (
    <section
      className={cn(
        'relative overflow-hidden bg-[#18221d] text-white',
        aspectRatio
          ? 'min-h-[640px] md:min-h-[88vh] lg:h-[max(30rem,var(--hero-height))] lg:min-h-0'
          : 'min-h-[640px] md:min-h-[88vh]',
        className,
      )}
      style={
        aspectRatio ? ({ '--hero-height': `${100 / aspectRatio}vw` } as CSSProperties) : undefined
      }
    >
      <Swiper
        modules={[A11y, Autoplay, EffectFade, Keyboard, Pagination]}
        onSwiper={setSwiper}
        effect="fade"
        fadeEffect={{ crossFade: true }}
        keyboard={{ enabled: true }}
        pagination={{ clickable: true }}
        autoplay={
          autoplayDelay && !reducedMotion
            ? { delay: autoplayDelay, disableOnInteraction: false, pauseOnMouseEnter: true }
            : false
        }
        loop={slides.length > 1}
        className="absolute inset-0 h-full [&_.swiper-pagination-bullet]:!h-1 [&_.swiper-pagination-bullet]:!w-12 [&_.swiper-pagination-bullet]:!rounded-none [&_.swiper-pagination-bullet]:!bg-white [&_.swiper-pagination]:!bottom-10"
      >
        {slides.map((slide, index) => (
          <SwiperSlide key={slide.id}>
            <article className={cn('relative h-full', height)}>
              <Image
                src={slide.image.src}
                alt={slide.image.alt}
                fill
                priority={index === 0}
                className="object-cover"
                sizes="100vw"
              />
              {overlay ? (
                <>
                  <div className="absolute inset-0 bg-gradient-to-r from-[#07120c]/90 via-[#07120c]/45 to-transparent" />
                  <div className="absolute inset-0 bg-gradient-to-t from-[#07120c]/60 via-transparent to-[#07120c]/15" />
                </>
              ) : null}

              <div
                className={cn(
                  'container relative flex items-start pb-28 pt-20 md:items-center md:py-28',
                  height,
                  aspectRatio && 'lg:py-16',
                )}
              >
                <div className="max-w-4xl">
                  {slide.eyebrow ? (
                    <p className="text-xs font-bold uppercase tracking-[0.26em] text-white/80">
                      {slide.eyebrow}
                    </p>
                  ) : null}
                  <h1 className="mt-6 max-w-4xl font-serif text-3xl leading-[1.05] tracking-[-0.03em] sm:text-4xl lg:text-5xl">
                    {slide.title}
                  </h1>
                  {slide.subtitle ? (
                    <p className="mt-6 max-w-xl text-xl font-medium leading-8 text-primary">
                      {slide.subtitle}
                    </p>
                  ) : null}
                  {slide.description ? (
                    <p
                      className={cn(
                        'max-w-2xl whitespace-pre-line leading-7 text-white/80',
                        slide.subtitle ? 'mt-2 text-base' : 'mt-7 text-lg leading-8',
                      )}
                    >
                      {slide.description}
                    </p>
                  ) : null}
                  {slide.action ? (
                    <Link
                      href={slide.action.href}
                      className="mt-9 inline-flex items-center gap-3 border-b border-white pb-2 text-sm font-semibold transition hover:gap-5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white"
                    >
                      {slide.action.label}
                      <ArrowRight className="h-4 w-4" aria-hidden />
                    </Link>
                  ) : null}
                </div>
              </div>
            </article>
          </SwiperSlide>
        ))}
      </Swiper>

      {arrows && slides.length > 1 ? (
        <div className="pointer-events-none absolute inset-x-0 bottom-[1.6rem] z-10 flex justify-center">
          <div
            className="flex items-center justify-between [&>button]:pointer-events-auto"
            style={{ width: slides.length * 56 + 104 }}
          >
            <button
              type="button"
              aria-label={arrows.previous}
              onClick={() => swiper?.slidePrev()}
              className={arrowClass}
            >
              <ChevronLeft className="h-4 w-4" aria-hidden />
            </button>
            <button
              type="button"
              aria-label={arrows.next}
              onClick={() => swiper?.slideNext()}
              className={arrowClass}
            >
              <ChevronRight className="h-4 w-4" aria-hidden />
            </button>
          </div>
        </div>
      ) : null}

      {scrollLabel ? (
        <a
          href="#conteudo"
          className="absolute bottom-8 left-6 z-10 hidden items-center gap-3 text-xs font-semibold uppercase tracking-[0.18em] text-white/70 transition hover:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white md:flex lg:left-12"
        >
          <ArrowDown className="h-4 w-4" aria-hidden />
          {scrollLabel}
        </a>
      ) : null}
    </section>
  )
}

import Link from 'next/link'
import { ChevronRight } from 'lucide-react'
import { cn } from '@/lib/utils'

export type PageHeaderProps = {
  title: string
  description?: string
  eyebrow?: string
  breadcrumbs?: Array<{ label: string; href?: string }>
  align?: 'left' | 'center'
  size?: 'default' | 'compact'
  variant?: 'muted' | 'primary'
  className?: string
}

export function PageHeader({
  title,
  description,
  eyebrow,
  breadcrumbs,
  align = 'left',
  size = 'default',
  variant = 'muted',
  className,
}: PageHeaderProps) {
  const compact = size === 'compact'
  const primary = variant === 'primary'

  return (
    <header
      className={cn(
        primary
          ? 'bg-primary bg-gradient-to-br from-primary to-primary/80 text-primary-foreground'
          : 'border-b bg-muted/30',
        className,
      )}
    >
      <div
        className={cn(
          'container',
          compact ? 'py-8 md:py-10' : 'py-14 md:py-20',
          align === 'center' && 'text-center',
        )}
      >
        {breadcrumbs?.length ? (
          <nav
            aria-label="Navegação estrutural"
            className={cn(compact ? 'mb-3' : 'mb-6', align === 'center' && 'flex justify-center')}
          >
            <ol
              className={cn(
                'flex flex-wrap items-center gap-1',
                compact ? 'text-xs' : 'text-sm',
                primary ? 'text-primary-foreground/70' : 'text-muted-foreground',
              )}
            >
              {breadcrumbs.map((item, index) => (
                <li key={`${item.label}-${index}`} className="flex items-center gap-1">
                  {index > 0 ? (
                    <ChevronRight className={compact ? 'h-3 w-3' : 'h-4 w-4'} aria-hidden="true" />
                  ) : null}
                  {item.href ? (
                    <Link
                      href={item.href}
                      className={cn(
                        'hover:underline',
                        primary ? 'hover:text-primary-foreground' : 'hover:text-foreground',
                      )}
                    >
                      {item.label}
                    </Link>
                  ) : (
                    <span
                      aria-current="page"
                      className={cn(primary && 'font-medium text-primary-foreground')}
                    >
                      {item.label}
                    </span>
                  )}
                </li>
              ))}
            </ol>
          </nav>
        ) : null}
        {eyebrow ? (
          <p
            className={cn(
              'font-semibold uppercase tracking-widest',
              compact ? 'mb-2 text-xs' : 'mb-3 text-sm',
              primary ? 'text-primary-foreground/80' : 'text-primary',
            )}
          >
            {eyebrow}
          </p>
        ) : null}
        <h1
          className={cn(
            'font-bold tracking-tight',
            compact ? 'text-2xl sm:text-3xl' : 'text-4xl sm:text-5xl',
          )}
        >
          {title}
        </h1>
        {description ? (
          <p
            className={cn(
              'max-w-2xl',
              compact ? 'mt-2 text-base' : 'mt-4 text-lg',
              primary ? 'text-primary-foreground/80' : 'text-muted-foreground',
              align === 'center' && 'mx-auto',
            )}
          >
            {description}
          </p>
        ) : null}
      </div>
    </header>
  )
