'use client'

import Image from 'next/image'
import type { ReactNode } from 'react'
import { motion, useReducedMotion } from 'framer-motion'
import { ArrowRight } from 'lucide-react'
import { cn } from '@/lib/utils'

export type PillarsHeroProps = {
  title: string
  description?: string
  eyebrow?: string
  primaryAction?: { label: string; href: string }
  secondaryAction?: { label: string; href: string }
  chips?: string[]
  pillars?: Array<{ title: string; description: string; icon?: ReactNode }>
  image: { src: string; alt: string }
  stat?: { value: string; label: string }
  className?: string
}

export function PillarsHero({
  title,
  description,
  eyebrow,
  primaryAction,
  secondaryAction,
  chips = [],
  pillars = [],
  image,
  stat,
  className,
}: PillarsHeroProps) {
  const reduceMotion = useReducedMotion()
  const enter = (delay: number) =>
    reduceMotion
      ? {}
      : {
          initial: { opacity: 0, y: 24 },
          animate: { opacity: 1, y: 0 },
          transition: { duration: 0.6, delay, ease: [0.22, 1, 0.36, 1] },
        }

  return (
    <section className={cn('relative overflow-hidden py-16 md:py-24', className)}>
      <div
        className="pointer-events-none absolute -right-32 -top-32 h-96 w-96 rounded-full bg-primary/15 blur-3xl"
        aria-hidden="true"
      />
      <div className="container grid items-center gap-12 lg:grid-cols-[1.1fr_0.9fr]">
        <div>
          {eyebrow ? (
            <motion.p
              {...enter(0)}
              className="font-mono text-sm font-semibold uppercase tracking-widest text-primary"
            >
              {'// '}
              {eyebrow}
            </motion.p>
          ) : null}
          <motion.h1
            {...enter(0.08)}
            className="mt-4 text-4xl font-bold leading-tight tracking-tight md:text-5xl lg:text-6xl"
          >
            {title}
          </motion.h1>
          {description ? (
            <motion.p
              {...enter(0.16)}
              className="mt-6 max-w-xl text-lg leading-8 text-muted-foreground"
            >
              {description}
            </motion.p>
          ) : null}
          {primaryAction || secondaryAction ? (
            <motion.div {...enter(0.24)} className="mt-8 flex flex-wrap gap-3">
              {primaryAction ? (
                <a
                  href={primaryAction.href}
                  className="group inline-flex items-center gap-2 rounded-full bg-primary px-6 py-3 text-sm font-semibold text-primary-foreground transition hover:bg-primary-hover"
                >
                  {primaryAction.label}
                  <ArrowRight className="h-4 w-4 transition group-hover:translate-x-1" />
                </a>
              ) : null}
              {secondaryAction ? (
                <a
                  href={secondaryAction.href}
                  className="inline-flex items-center rounded-full border px-6 py-3 text-sm font-semibold transition hover:border-primary hover:text-primary"
                >
                  {secondaryAction.label}
                </a>
              ) : null}
            </motion.div>
          ) : null}
          {chips.length ? (
            <motion.ul {...enter(0.32)} className="mt-8 flex flex-wrap gap-2">
              {chips.map((chip) => (
                <li
                  key={chip}
                  className="inline-flex items-center gap-2 rounded-full bg-muted px-3 py-1.5 text-xs font-semibold"
                >
                  <span className="h-1.5 w-1.5 rounded-full bg-primary" aria-hidden="true" />
                  {chip}
                </li>
              ))}
            </motion.ul>
          ) : null}
        </div>

        <motion.div {...enter(0.2)} className="relative">
          <div className="relative aspect-[4/5] overflow-hidden rounded-3xl bg-muted shadow-2xl">
            <Image
              src={image.src}
              alt={image.alt}
              fill
              priority
              className="object-cover"
              sizes="(min-width: 1024px) 40vw, 100vw"
            />
          </div>
          {stat ? (
            <motion.div
              animate={reduceMotion ? undefined : { y: [0, -10, 0] }}
              transition={{ duration: 5, repeat: Infinity, ease: 'easeInOut' }}
              className="absolute -bottom-6 left-4 max-w-[14rem] rounded-2xl bg-primary p-5 text-primary-foreground shadow-xl md:-left-8"
            >
              <p className="text-4xl font-bold">{stat.value}</p>
              <p className="mt-1 text-sm opacity-85">{stat.label}</p>
            </motion.div>
          ) : null}
        </motion.div>
      </div>

      {pillars.length ? (
        <div className="container mt-16">
          <ul className="grid gap-px overflow-hidden rounded-2xl border bg-border md:grid-cols-3">
            {pillars.map((pillar, index) => (
              <motion.li
                key={pillar.title}
                initial={reduceMotion ? false : { opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true, amount: 0.4 }}
                transition={{ duration: 0.5, delay: index * 0.1 }}
                className="group bg-background p-6 transition hover:bg-primary/5"
              >
                {pillar.icon ? (
                  <span className="mb-4 flex h-11 w-11 items-center justify-center rounded-xl bg-primary/10 text-primary transition group-hover:bg-primary group-hover:text-primary-foreground">
                    {pillar.icon}
                  </span>
                ) : null}
                <h2 className="text-lg font-semibold">{pillar.title}</h2>
                <p className="mt-2 text-sm leading-6 text-muted-foreground">{pillar.description}</p>
              </motion.li>
            ))}
          </ul>
        </div>
      ) : null}
    </section>
  )
}

'use client'

import { useRef, useState, type ReactNode } from 'react'
import Image from 'next/image'
import { ChevronLeft, ChevronRight } from 'lucide-react'
import type { Swiper as SwiperInstance } from 'swiper'
import { A11y, Autoplay, EffectFade, Keyboard } from 'swiper/modules'
import { Swiper, SwiperSlide } from 'swiper/react'

import { AccentButton } from '@/components/library/primitives/AccentButton'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { useReducedMotion } from '@/components/library/motion/useReducedMotion'
import { cn } from '@/lib/utils'

import 'swiper/css'
import 'swiper/css/effect-fade'

export type ProgressBannerSlide = {
  id: string
  title: string
  image: { src: string; alt: string }
  mobileImage?: string
  eyebrow?: string
  subtitle?: string
  description?: string
  action?: { label: string; href: string }
}

export type ProgressBannerSocialLink = {
  label: string
  href: string
  icon: ReactNode
}

export type ProgressBannerCarouselProps = {
  slides: readonly ProgressBannerSlide[]
  tone?: AccentTone
  autoplayDelay?: number
  showArrows?: boolean
  socialLinks?: readonly ProgressBannerSocialLink[]
  className?: string
}

const overlays: Record<AccentTone, string[]> = {
  glow: [
    'bg-gradient-to-r from-[#121212]/95 via-[#121212]/60 to-[#221d2f]/20',
    'bg-gradient-to-t from-[#121212]/80 via-transparent to-[#121212]/40',
  ],
  industrial: [
    'bg-gradient-to-r from-slate-950/90 via-slate-950/55 to-slate-950/25',
    'bg-gradient-to-t from-slate-950/70 via-transparent to-slate-950/30',
  ],
  'industrial-dark': [
    'bg-gradient-to-r from-slate-950/90 via-slate-950/55 to-slate-950/25',
    'bg-gradient-to-t from-slate-950/70 via-transparent to-slate-950/30',
  ],
}

/** Banner em tela cheia com fade, barras de progresso do autoplay e trilho de redes sociais. */
export function ProgressBannerCarousel({
  slides,
  tone = 'glow',
  autoplayDelay = 6000,
  showArrows = true,
  socialLinks = [],
  className,
}: ProgressBannerCarouselProps) {
  const t = getAccentTone(tone)
  const isGlow = tone === 'glow'
  const reducedMotion = useReducedMotion()
  const [swiper, setSwiper] = useState<SwiperInstance | null>(null)
  const [activeIndex, setActiveIndex] = useState(0)
  const progressRefs = useRef<(HTMLSpanElement | null)[]>([])

  const resetProgress = (): void => {
    progressRefs.current.forEach((element) => {
      if (element) element.style.transform = 'scaleX(0)'
    })
  }

  const textReveal = (isActive: boolean, delay: number) => ({
    className: cn(
      'transition-all duration-700 ease-out motion-reduce:transition-none',
      isActive ? 'translate-y-0 opacity-100' : 'translate-y-4 opacity-0',
    ),
    style: { transitionDelay: isActive ? `${delay}ms` : '0ms' },
  })

  return (
    <section
      className={cn('relative h-[86svh] w-full overflow-hidden', t.section, className)}
      aria-roledescription="carrossel"
    >
      {!isGlow ? (
        <div
          className="pointer-events-none absolute inset-x-0 bottom-0 z-30 h-32 bg-gradient-to-t from-slate-950 from-15% via-slate-950/70 to-transparent md:h-40"
          aria-hidden
        />
      ) : null}

      <Swiper
        modules={[A11y, Autoplay, EffectFade, Keyboard]}
        effect="fade"
        fadeEffect={{ crossFade: true }}
        speed={1100}
        loop={slides.length > 1}
        keyboard={{ enabled: true }}
        autoplay={
          reducedMotion || slides.length < 2
            ? false
            : { delay: autoplayDelay, disableOnInteraction: false }
        }
        onSwiper={setSwiper}
        onSlideChange={(instance) => setActiveIndex(instance.realIndex)}
        onSlideChangeTransitionStart={resetProgress}
        onAutoplayTimeLeft={(instance, _timeLeft, percentage) => {
          const element = progressRefs.current[instance.realIndex]
          if (element) {
            element.style.transform = `scaleX(${Math.max(0, Math.min(1, 1 - percentage))})`
          }
        }}
        className="h-full w-full"
      >
        {slides.map((slide, index) => (
          <SwiperSlide key={slide.id} className="!h-full">
            {({ isActive }) => (
              <div className="relative h-full w-full">
                <Image
                  src={slide.image.src}
                  alt={slide.image.alt}
                  fill
                  priority={index === 0}
                  sizes="100vw"
                  className={cn('object-cover', slide.mobileImage && 'hidden md:block')}
                />
                {slide.mobileImage ? (
                  <Image
                    src={slide.mobileImage}
                    alt={slide.image.alt}
                    fill
                    priority={index === 0}
                    sizes="100vw"
                    className="block object-cover md:hidden"
                  />
                ) : null}
                {overlays[tone].map((overlay) => (
                  <div key={overlay} className={cn('absolute inset-0', overlay)} aria-hidden />
                ))}

                <div className="absolute inset-0 flex items-center pb-28 pt-6 md:pb-24 md:pt-0">
                  <div className="container relative z-10 md:pr-20 lg:pr-24">
                    <div className="max-w-xl text-left text-white md:max-w-2xl">
                      {slide.eyebrow ? (
                        <div {...textReveal(isActive, 150)}>
                          <div className="mb-4 flex items-center gap-3 md:mb-5">
                            <span className={cn('h-px w-8 md:w-10', t.line)} aria-hidden />
                            <span
                              className={cn(
                                'text-[0.65rem] font-medium uppercase tracking-[0.28em] md:text-xs',
                                isGlow ? 'text-[#ffb0eb]' : 'text-amber-500',
                              )}
                            >
                              {slide.eyebrow}
                            </span>
                          </div>
                        </div>
                      ) : null}

                      <div {...textReveal(isActive, 300)}>
                        {(() => {
                          const Title = index === 0 ? 'h1' : 'p'
                          return (
                            <Title
                              className={cn(
                                'mb-3 text-[1.75rem] font-semibold leading-[1.2] sm:text-3xl md:mb-4 md:text-5xl lg:text-[3.5rem]',
                                isGlow
                                  ? 'w-fit bg-gradient-to-r from-[#c642a5] via-[#ffb0eb] to-[#7c39cf] bg-clip-text text-transparent'
                                  : 'uppercase leading-[1.15] tracking-wide',
                              )}
                            >
                              {slide.title}
                            </Title>
                          )
                        })()}
                      </div>

                      {slide.subtitle ? (
                        <div {...textReveal(isActive, 450)}>
                          <p className="mb-3 text-base font-medium leading-snug text-white md:mb-4 md:text-xl lg:text-2xl">
                            {slide.subtitle}
                          </p>
                        </div>
                      ) : null}

                      {slide.description ? (
                        <div {...textReveal(isActive, 600)}>
                          <p
                            className={cn(
                              'mb-6 max-w-md text-sm leading-relaxed md:mb-8 md:max-w-lg md:text-base lg:text-lg',
                              isGlow ? 'text-[#c1c1c1]' : 'text-slate-300/90',
                            )}
                          >
                            {slide.description}
                          </p>
                        </div>
                      ) : null}

                      {slide.action ? (
                        <div {...textReveal(isActive, 750)}>
                          <AccentButton
                            href={slide.action.href}
                            tone={isGlow ? 'glow' : 'industrial-dark'}
                            size={isGlow ? 'md' : 'lg'}
                          >
                            {slide.action.label}
                          </AccentButton>
                        </div>
                      ) : null}
                    </div>
                  </div>
                </div>
              </div>
            )}
          </SwiperSlide>
        ))}
      </Swiper>

      {slides.length > 1 ? (
        <div className="absolute bottom-8 left-1/2 z-40 flex -translate-x-1/2 items-center gap-3 md:bottom-10 md:gap-4">
          {showArrows ? (
            <button
              type="button"
              onClick={() => swiper?.slidePrev()}
              className={cn(
                'flex h-10 w-10 shrink-0 items-center justify-center transition-colors',
                t.iconButton,
                t.focus,
              )}
              aria-label="Slide anterior"
            >
              <ChevronLeft className="h-5 w-5" />
            </button>
          ) : null}

          <div className="flex items-center gap-2">
            {slides.map((slide, index) => {
              const active = index === activeIndex
              return (
                <button
                  key={slide.id}
                  type="button"
                  onClick={() => swiper?.slideToLoop(index)}
                  className={cn('inline-flex items-center py-2', t.focus)}
                  aria-label={`Ir para o slide ${index + 1}`}
                  aria-current={active ? 'true' : undefined}
                >
                  <span
                    className={cn(
                      'relative block h-0.5 overflow-hidden bg-white/35 transition-[width] duration-300',
                      active ? 'w-[3.25rem] bg-white/25' : 'w-10',
                    )}
                  >
                    <span
                      ref={(element) => {
                        progressRefs.current[index] = element
                      }}
                      className={cn(
                        'absolute inset-0 origin-left scale-x-0',
                        isGlow ? t.line : 'bg-amber-500',
                        reducedMotion && active && 'scale-x-100',
                      )}
                    />
                  </span>
                </button>
              )
            })}
          </div>

          {showArrows ? (
            <button
              type="button"
              onClick={() => swiper?.slideNext()}
              className={cn(
                'flex h-10 w-10 shrink-0 items-center justify-center transition-colors',
                t.iconButton,
                t.focus,
              )}
              aria-label="Próximo slide"
            >
              <ChevronRight className="h-5 w-5" />
            </button>
          ) : null}
        </div>
      ) : null}

      {socialLinks.length ? (
        <aside
          className="absolute right-4 top-[42%] z-40 hidden -translate-y-1/2 md:right-6 md:block lg:right-8"
          aria-label="Redes sociais"
        >
          <div className="flex flex-col items-center gap-5">
            <span
              className={cn(
                'w-px',
                isGlow
                  ? 'h-14 bg-gradient-to-b from-transparent via-[#c642a5] to-transparent'
                  : 'h-7 bg-white/80',
              )}
              aria-hidden
            />
            {socialLinks.map((item) => (
              <a
                key={item.label}
                href={item.href}
                target="_blank"
                rel="noopener noreferrer"
                aria-label={item.label}
                className={cn(
                  'text-white transition-colors duration-300 [&_svg]:h-[15px] [&_svg]:w-[15px]',
                  isGlow ? 'hover:text-[#ffb0eb]' : 'hover:text-amber-500',
                  t.focus,
                )}
              >
                {item.icon}
              </a>
            ))}
            <span
              className={cn(
                'w-px',
                isGlow
                  ? 'h-14 bg-gradient-to-b from-transparent via-[#7c39cf] to-transparent'
                  : 'h-7 bg-white/80',
              )}
              aria-hidden
            />
          </div>
        </aside>
      ) : null}
    </section>
  )
}

'use client'

import Image from 'next/image'
import { useCallback, useEffect, useState } from 'react'
import { AnimatePresence, motion, useReducedMotion } from 'framer-motion'
import { Check, ChevronLeft, ChevronRight, Copy } from 'lucide-react'
import { cn } from '@/lib/utils'

export type PromoSlide = {
  id: string
  title: string
  description?: string
  badge?: string
  coupon?: string
  action?: { label: string; href: string }
  image: { src: string; alt: string }
}

export type PromoCouponCarouselProps = {
  slides: PromoSlide[]
  interval?: number
  couponLabel?: string
  className?: string
}

export function PromoCouponCarousel({
  slides,
  interval = 6000,
  couponLabel = 'Cupom',
  className,
}: PromoCouponCarouselProps) {
  const [index, setIndex] = useState(0)
  const [paused, setPaused] = useState(false)
  const [copied, setCopied] = useState<string | null>(null)
  const reduceMotion = useReducedMotion()
  const total = slides.length
  const slide = slides[index]

  const go = useCallback(
    (step: number) => setIndex((current) => (current + step + total) % total),
    [total],
  )

  useEffect(() => {
    if (paused || reduceMotion || total < 2) return
    const timer = window.setTimeout(() => go(1), interval)
    return () => window.clearTimeout(timer)
  }, [go, index, interval, paused, reduceMotion, total])

  async function copyCoupon(code: string) {
    await navigator.clipboard?.writeText(code)
    setCopied(code)
    window.setTimeout(() => setCopied(null), 2000)
  }

  if (!slide) return null
  const pad = (value: number) => String(value).padStart(2, '0')

  return (
    <section
      className={cn('relative isolate overflow-hidden bg-foreground text-background', className)}
      aria-roledescription="carrossel"
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
    >
      <AnimatePresence mode="wait">
        <motion.div
          key={slide.id}
          initial={reduceMotion ? false : { opacity: 0, scale: 1.06 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={reduceMotion ? undefined : { opacity: 0 }}
          transition={{ duration: 0.7 }}
          className="absolute inset-0 -z-10"
        >
          <Image
            src={slide.image.src}
            alt={slide.image.alt}
            fill
            className="object-cover"
            sizes="100vw"
          />
          <div className="absolute inset-0 bg-gradient-to-r from-black/85 via-black/55 to-transparent" />
        </motion.div>
      </AnimatePresence>

      <div className="container flex min-h-[32rem] flex-col justify-center py-16">
        <AnimatePresence mode="wait">
          <motion.div
            key={slide.id}
            initial={reduceMotion ? false : { opacity: 0, x: -24 }}
            animate={{ opacity: 1, x: 0 }}
            exit={reduceMotion ? undefined : { opacity: 0, x: 24 }}
            transition={{ duration: 0.45 }}
            className="max-w-xl text-white"
            aria-live="polite"
          >
            {slide.badge ? (
              <span className="inline-flex rounded-full bg-primary px-3 py-1 text-xs font-bold uppercase tracking-wider text-primary-foreground">
                {slide.badge}
              </span>
            ) : null}
            <h2 className="mt-4 text-4xl font-bold leading-tight md:text-5xl">{slide.title}</h2>
            {slide.description ? (
              <p className="mt-4 text-lg leading-8 text-white/80">{slide.description}</p>
            ) : null}
            <div className="mt-8 flex flex-wrap items-center gap-3">
              {slide.action ? (
                <a
                  href={slide.action.href}
                  className="inline-flex rounded-full bg-primary px-6 py-3 text-sm font-semibold text-primary-foreground transition hover:bg-primary-hover"
                >
                  {slide.action.label}
                </a>
              ) : null}
              {slide.coupon ? (
                <button
                  type="button"
                  onClick={() => copyCoupon(slide.coupon as string)}
                  className="inline-flex items-center gap-3 rounded-full border border-dashed border-white/60 px-5 py-3 text-sm transition hover:border-white hover:bg-white/10"
                >
                  <span className="text-white/70">{couponLabel}</span>
                  <strong className="font-mono tracking-wider">{slide.coupon}</strong>
                  {copied === slide.coupon ? (
                    <Check className="h-4 w-4 text-green-400" aria-label="Copiado" />
                  ) : (
                    <Copy className="h-4 w-4" aria-label="Copiar cupom" />
                  )}
                </button>
              ) : null}
            </div>
          </motion.div>
        </AnimatePresence>

        {total > 1 ? (
          <div className="mt-12 flex items-center gap-4 text-white">
            <button
              type="button"
              onClick={() => go(-1)}
              className="flex h-10 w-10 items-center justify-center rounded-full border border-white/40 transition hover:bg-white hover:text-black"
              aria-label="Slide anterior"
            >
              <ChevronLeft className="h-5 w-5" />
            </button>
            <span className="font-mono text-sm tabular-nums">
              {pad(index + 1)}/{pad(total)}
            </span>
            <div className="h-0.5 w-32 overflow-hidden rounded bg-white/25">
              <motion.div
                key={`${slide.id}-${paused}`}
                className="h-full bg-primary"
                initial={{ width: '0%' }}
                animate={{ width: paused || reduceMotion ? '0%' : '100%' }}
                transition={{ duration: interval / 1000, ease: 'linear' }}
              />
            </div>
            <button
              type="button"
              onClick={() => go(1)}
              className="flex h-10 w-10 items-center justify-center rounded-full border border-white/40 transition hover:bg-white hover:text-black"
              aria-label="Próximo slide"
            >
              <ChevronRight className="h-5 w-5" />
            </button>
          </div>
        ) : null}
      </div>
    </section>
  )
}

'use client'

import { useState } from 'react'
import { useAutoAnimate } from '@formkit/auto-animate/react'
import { GripVertical, Plus, X } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type AnimatedListItem = {
  id: string
  title: string
  description?: string
}

export type AnimatedListProps = {
  initialItems: AnimatedListItem[]
  allowAdd?: boolean
  allowRemove?: boolean
  addLabel?: string
  className?: string
  onChange?: (items: AnimatedListItem[]) => void
}

export function AnimatedList({
  initialItems,
  allowAdd = true,
  allowRemove = true,
  addLabel = 'Adicionar item',
  className,
  onChange,
}: AnimatedListProps) {
  const [items, setItems] = useState(initialItems)
  const [listRef] = useAutoAnimate<HTMLUListElement>()

  function updateItems(nextItems: AnimatedListItem[]) {
    setItems(nextItems)
    onChange?.(nextItems)
  }

  function addItem() {
    const index = items.length + 1
    updateItems([
      ...items,
      {
        id: `item-${Date.now()}`,
        title: `Novo item ${index}`,
        description: 'Conteúdo adicionado com transição automática.',
      },
    ])
  }

  return (
    <div className={cn('space-y-3', className)}>
      <ul ref={listRef} className="space-y-2" aria-live="polite">
        {items.map((item) => (
          <li
            key={item.id}
            className="flex items-center gap-3 rounded-xl border bg-card p-3 shadow-sm"
          >
            <GripVertical className="h-4 w-4 shrink-0 text-muted-foreground" aria-hidden="true" />
            <div className="min-w-0 flex-1">
              <p className="font-medium">{item.title}</p>
              {item.description ? (
                <p className="truncate text-sm text-muted-foreground">{item.description}</p>
              ) : null}
            </div>
            {allowRemove ? (
              <Button
                type="button"
                size="sm"
                variant="ghost"
                onClick={() => updateItems(items.filter((current) => current.id !== item.id))}
                aria-label={`Remover ${item.title}`}
              >
                <X className="h-4 w-4" />
              </Button>
            ) : null}
          </li>
        ))}
      </ul>
      {allowAdd ? (
        <Button type="button" size="sm" variant="outline" onClick={addItem}>
          <Plus className="mr-2 h-4 w-4" />
          {addLabel}
        </Button>
      ) : null}
    </div>
  )
}

'use client'

import { useEffect, useMemo, useState } from 'react'
import Image from 'next/image'
import Link from 'next/link'
import { useAutoAnimate } from '@formkit/auto-animate/react'
import { ArrowUpRight } from 'lucide-react'

import { cn } from '@/lib/utils'

import { useReducedMotion } from './useReducedMotion'

export type AutoAnimateGalleryItem = {
  id: string
  title: string
  category: string
  description?: string
  image: { src: string; alt: string }
  href?: string
}

export type AutoAnimateGallerySectionProps = {
  title?: string
  description?: string
  items: readonly AutoAnimateGalleryItem[]
  allLabel?: string
  columns?: 2 | 3 | 4
  className?: string
}

export function AutoAnimateGallerySection({
  title,
  description,
  items,
  allLabel = 'Todos',
  columns = 3,
  className,
}: AutoAnimateGallerySectionProps) {
  const [category, setCategory] = useState('all')
  const reducedMotion = useReducedMotion()
  const [gridRef, enableAnimations] = useAutoAnimate<HTMLDivElement>({
    duration: 320,
    easing: 'ease-out',
  })
  const categories = useMemo(() => Array.from(new Set(items.map((item) => item.category))), [items])
  const visibleItems =
    category === 'all' ? items : items.filter((item) => item.category === category)
  const columnsClass = {
    2: 'md:grid-cols-2',
    3: 'md:grid-cols-2 lg:grid-cols-3',
    4: 'md:grid-cols-2 lg:grid-cols-4',
  }[columns]

  useEffect(() => {
    enableAnimations(!reducedMotion)
  }, [enableAnimations, reducedMotion])

  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        <div className="flex flex-col gap-7 lg:flex-row lg:items-end lg:justify-between">
          <header className="max-w-2xl">
            {title ? (
              <h2 className="text-3xl font-bold tracking-tight md:text-4xl lg:text-5xl">{title}</h2>
            ) : null}
            {description ? (
              <p className="mt-4 leading-7 text-muted-foreground">{description}</p>
            ) : null}
          </header>
          <div
            className="flex max-w-full gap-2 overflow-x-auto pb-1 [scrollbar-width:none] max-sm:flex-wrap [&::-webkit-scrollbar]:hidden"
            role="group"
            aria-label="Filtrar galeria"
          >
            {[
              { value: 'all', label: allLabel },
              ...categories.map((item) => ({ value: item, label: item })),
            ].map((filter) => (
              <button
                type="button"
                key={filter.value}
                onClick={() => setCategory(filter.value)}
                aria-pressed={category === filter.value}
                className={cn(
                  'shrink-0 rounded-full border px-4 py-2 text-sm font-medium transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
                  category === filter.value
                    ? 'border-primary bg-primary text-primary-foreground'
                    : 'bg-background hover:border-primary/40 hover:text-primary',
                )}
              >
                {filter.label}
              </button>
            ))}
          </div>
        </div>

        <div ref={gridRef} className={cn('mt-10 grid gap-5', columnsClass)}>
          {visibleItems.map((item, index) => (
            <article
              key={item.id}
              className={cn(
                'group overflow-hidden rounded-3xl border bg-card shadow-sm',
                columns !== 4 && index === 0 && visibleItems.length > 2 && 'md:col-span-2',
              )}
            >
              <div
                className={cn(
                  'relative overflow-hidden bg-muted',
                  index === 0 && visibleItems.length > 2 && columns !== 4
                    ? 'aspect-[4/3] md:aspect-[16/8]'
                    : 'aspect-[4/3]',
                )}
              >
                <Image
                  src={item.image.src}
                  alt={item.image.alt}
                  fill
                  className="object-cover transition-transform duration-700 group-hover:scale-105"
                  sizes="(min-width: 1024px) 40vw, 100vw"
                />
                <span className="absolute left-4 top-4 rounded-full bg-background/90 px-3 py-1 text-xs font-bold backdrop-blur">
                  {item.category}
                </span>
