'use client'

import { useRef } from 'react'
import { useGSAP } from '@/lib/hooks/useGSAP'
import { prefersReducedMotion, useReducedMotion } from './useReducedMotion'

export type CounterProps = {
  value: number
  from?: number
  duration?: number
  delay?: number
  decimals?: number
  locale?: string
  prefix?: string
  suffix?: string
  className?: string
  trigger?: 'mount' | 'scroll'
  formatter?: (value: number) => string
}

export function Counter({
  value,
  from = 0,
  duration = 1.5,
  delay = 0,
  decimals = 0,
  locale = 'pt-BR',
  prefix = '',
  suffix = '',
  className,
  trigger = 'scroll',
  formatter,
}: CounterProps) {
  const root = useRef<HTMLSpanElement>(null)
  const output = useRef<HTMLSpanElement>(null)
  const reduced = useReducedMotion()
  const safeValue = Number.isFinite(value) ? value : 0
  const safeFrom = Number.isFinite(from) ? from : 0
  const precision = Math.min(20, Math.max(0, Math.trunc(decimals)))
  const numberFormat = new Intl.NumberFormat(locale, {
    minimumFractionDigits: precision,
    maximumFractionDigits: precision,
  })
  const format = (current: number): string =>
    `${prefix}${formatter ? formatter(current) : numberFormat.format(current)}${suffix}`
  const finalText = format(safeValue)

  useGSAP(
    ({ gsap }) => {
      const element = root.current
      const text = output.current
      if (!element || !text) return

      if (reduced || prefersReducedMotion()) {
        text.textContent = finalText
        return
      }

      const state = { value: safeFrom }
      gsap.to(state, {
        value: safeValue,
        duration,
        delay,
        ease: 'power2.out',
        onStart: () => {
          text.textContent = format(safeFrom)
        },
        onUpdate: () => {
          text.textContent = format(state.value)
        },
        onComplete: () => {
          text.textContent = finalText
        },
        scrollTrigger:
          trigger === 'scroll'
            ? {
                trigger: element,
                start: 'top 90%',
                once: true,
              }
            : undefined,
      })

      return () => {
        text.textContent = finalText
      }
    },
    [
      delay,
      duration,
      finalText,
      formatter,
      locale,
      precision,
      prefix,
      reduced,
      safeFrom,
      safeValue,
      suffix,
      trigger,
    ],
    root,
  )

  return (
    <span ref={root} className={className} aria-label={finalText}>
      <span ref={output} aria-hidden="true">
        {finalText}
      </span>
    </span>
  )
}

'use client'

import { useEffect, useRef } from 'react'
import { cn } from '@/lib/utils'
import { useReducedMotion } from './useReducedMotion'

export type DepthTextProps = {
  text: string
  as?: 'h1' | 'h2' | 'h3' | 'p' | 'span'
  layers?: number
  depth?: number
  className?: string
  layerClassName?: string
}

export function DepthText({
  text,
  as: Tag = 'h2',
  layers = 12,
  depth = 1.4,
  className,
  layerClassName = 'text-primary',
}: DepthTextProps) {
  const rootRef = useRef<HTMLElement>(null)
  const reduced = useReducedMotion()

  useEffect(() => {
    const root = rootRef.current
    if (!root) return

    const rest = { x: 0.7, y: 0.7 }
    const current = { ...rest }
    const target = { ...rest }
    let frame = 0

    const apply = () => {
      root.style.setProperty('--depth-x', `${current.x * depth}px`)
      root.style.setProperty('--depth-y', `${current.y * depth}px`)
    }
    apply()
    if (reduced) return

    const tick = () => {
      current.x += (target.x - current.x) * 0.08
      current.y += (target.y - current.y) * 0.08
      apply()
      frame = requestAnimationFrame(tick)
    }

    const move = (event: PointerEvent) => {
      const bounds = root.getBoundingClientRect()
      const clamp = (value: number) => Math.max(-1, Math.min(1, value))
      target.x = -clamp(
        (event.clientX - (bounds.left + bounds.width / 2)) / (bounds.width / 2 + 200),
      )
      target.y = -clamp(
        (event.clientY - (bounds.top + bounds.height / 2)) / (bounds.height / 2 + 200),
      )
    }
    const leave = () => Object.assign(target, rest)

    window.addEventListener('pointermove', move)
    document.addEventListener('pointerleave', leave)
    frame = requestAnimationFrame(tick)
    return () => {
      cancelAnimationFrame(frame)
      window.removeEventListener('pointermove', move)
      document.removeEventListener('pointerleave', leave)
    }
  }, [depth, reduced])

  return (
    <Tag
      ref={rootRef as never}
      className={cn('relative inline-grid font-black leading-none tracking-tight', className)}
    >
      {Array.from({ length: layers }, (_, index) => {
        const layer = layers - index
        return (
          <span
            key={layer}
            aria-hidden="true"
            className={cn('col-start-1 row-start-1 select-none', layerClassName)}
            style={{
              opacity: 0.25 + 0.75 * (1 - layer / layers),
              transform: `translate3d(calc(var(--depth-x, 0px) * ${layer}), calc(var(--depth-y, 0px) * ${layer}), 0)`,
            }}
          >
            {text}
          </span>
        )
      })}
      <span className="relative col-start-1 row-start-1">{text}</span>
    </Tag>
  )
}

'use client'

import { useEffect, useRef, type ReactNode } from 'react'
import { cn } from '@/lib/utils'
import { useReducedMotion } from './useReducedMotion'

export type FluxLinesProps = {
  children?: ReactNode
  className?: string
  lineCount?: number
  amplitude?: number
  speed?: number
  magnetRadius?: number
  magnetStrength?: number
  color?: string
}

type Rgb = [number, number, number]

function toRgb(context: CanvasRenderingContext2D, color: string): Rgb {
  context.fillStyle = '#000'
  context.fillStyle = color
  const value = String(context.fillStyle)
  if (value.startsWith('#')) {
    const hex = parseInt(value.slice(1), 16)
    return [(hex >> 16) & 255, (hex >> 8) & 255, hex & 255]
  }
  const [r = 0, g = 0, b = 0] = value.match(/[\d.]+/g)?.map(Number) ?? []
  return [r, g, b]
}

const mix = (from: Rgb, to: Rgb, amount: number): Rgb =>
  from.map((value, index) => Math.round(value + (to[index] - value) * amount)) as Rgb

const rgba = ([r, g, b]: Rgb, alpha: number) => `rgba(${r}, ${g}, ${b}, ${alpha})`

export function FluxLines({
  children,
  className,
  lineCount = 26,
  amplitude = 38,
  speed = 1,
  magnetRadius = 170,
  magnetStrength = 1,
  color,
}: FluxLinesProps) {
  const rootRef = useRef<HTMLDivElement>(null)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const reduced = useReducedMotion()

  useEffect(() => {
    const root = rootRef.current
    const canvas = canvasRef.current
    const context = canvas?.getContext('2d')
    if (!root || !canvas || !context) return

    const primary = getComputedStyle(root).getPropertyValue('--primary').trim()
    const base = toRgb(context, color ?? (primary ? `hsl(${primary})` : '#a855f7'))
    const glow = mix(base, [255, 255, 255], 0.35)
    const highlight = mix(base, [255, 255, 255], 0.75)

    let width = 0
    let height = 0
    let frame = 0
    const pointer = { x: -9999, y: -9999, strength: 0, target: 0 }

    const resize = () => {
      const ratio = Math.min(window.devicePixelRatio || 1, 2)
      width = root.clientWidth
      height = root.clientHeight
      canvas.width = width * ratio
      canvas.height = height * ratio
      context.setTransform(ratio, 0, 0, ratio, 0, 0)
    }

    const tracePaths = (time: number) => {
      const t = time * 0.00035 * speed
      const step = 10
      context.beginPath()
      for (let line = 0; line < lineCount; line += 1) {
        const progress = lineCount > 1 ? line / (lineCount - 1) : 0.5
        const baseY = height * (0.08 + progress * 0.84)
        for (let x = -step; x <= width + step; x += step) {
          let px = x
          let py =
            baseY +
            Math.sin(x * 0.0042 + t * 2.1 + line * 0.33) * amplitude * 0.6 +
            Math.sin(x * 0.011 - t * 2.9 + line * 0.85) * amplitude * 0.22 +
            Math.sin(x * 0.0018 + t * 1.3 + progress * 5.5) * amplitude * 0.55
          const dx = px - pointer.x
          const dy = py - pointer.y
          const distance = Math.hypot(dx, dy)
          if (pointer.strength > 0.001 && distance < magnetRadius) {
            const force = (1 - distance / magnetRadius) ** 2 * pointer.strength * magnetStrength
            const angle = force * 1.6
            px = pointer.x + dx * Math.cos(angle) - dy * Math.sin(angle)
            py = pointer.y + dx * Math.sin(angle) + dy * Math.cos(angle)
          }
          if (x === -step) context.moveTo(px, py)
          else context.lineTo(px, py)
        }
      }
    }

    const draw = (time: number) => {
      pointer.strength += (pointer.target - pointer.strength) * 0.08
      context.clearRect(0, 0, width, height)
      context.globalCompositeOperation = 'lighter'
      context.lineWidth = 1.2
      tracePaths(time)

      context.shadowColor = rgba(glow, 0.9)
      context.shadowBlur = 10
      context.strokeStyle = rgba(glow, 0.32)
      context.stroke()

      if (pointer.strength > 0.01) {
        const radius = magnetRadius * 1.6
        const reveal = context.createRadialGradient(
          pointer.x,
          pointer.y,
          0,
          pointer.x,
          pointer.y,
          radius,
        )
        reveal.addColorStop(0, rgba(highlight, 0.95 * pointer.strength))
        reveal.addColorStop(1, rgba(highlight, 0))
        context.shadowColor = rgba(highlight, 0.9)
        context.shadowBlur = 16
        context.strokeStyle = reveal
        context.stroke()
      }
      context.shadowBlur = 0
      context.globalCompositeOperation = 'source-over'

      if (!reduced) frame = requestAnimationFrame(draw)
    }

    const move = (event: PointerEvent) => {
      const bounds = root.getBoundingClientRect()
      pointer.x = event.clientX - bounds.left
      pointer.y = event.clientY - bounds.top
      pointer.target = 1
      if (reduced) draw(0)
    }
    const leave = () => {
      pointer.target = 0
      if (reduced) {
        pointer.strength = 0
        draw(0)
      }
    }

    const observer = new ResizeObserver(() => {
      resize()
      if (reduced) draw(0)
    })
    observer.observe(root)
    resize()
    root.addEventListener('pointermove', move)
    root.addEventListener('pointerleave', leave)
    frame = requestAnimationFrame(draw)

    return () => {
      cancelAnimationFrame(frame)
      observer.disconnect()
      root.removeEventListener('pointermove', move)
      root.removeEventListener('pointerleave', leave)
    }
  }, [amplitude, color, lineCount, magnetRadius, magnetStrength, reduced, speed])

  return (
    <div
      ref={rootRef}
      className={cn('relative isolate overflow-hidden bg-slate-950 text-white', className)}
    >
      <canvas ref={canvasRef} className="absolute inset-0 -z-10 h-full w-full" aria-hidden="true" />
      {children}
    </div>
  )
}

'use client'

import { useRef } from 'react'
import Image from 'next/image'

import { useGSAP } from '@/lib/hooks/useGSAP'
import { cn } from '@/lib/utils'

import { prefersReducedMotion, useReducedMotion } from './useReducedMotion'

export type GSAPStoryItem = {
  id: string
  number?: string
  title: string
  description: string
  image: { src: string; alt: string }
}

export type GSAPStorySectionProps = {
  eyebrow?: string
  title: string
  description?: string
  items: readonly GSAPStoryItem[]
  pinHeading?: boolean
  className?: string
}

export function GSAPStorySection({
  eyebrow,
  title,
  description,
  items,
  pinHeading = true,
  className,
}: GSAPStorySectionProps) {
  const root = useRef<HTMLElement>(null)
  const reducedMotion = useReducedMotion()

  useGSAP(
    ({ gsap, ScrollTrigger }) => {
      const section = root.current
      if (!section || reducedMotion || prefersReducedMotion()) return

      const heading = section.querySelector('[data-gsap-heading]')
      const cards = gsap.utils.toArray<HTMLElement>('[data-gsap-card]', section)

      if (heading) {
        gsap.fromTo(
          heading,
          { y: 60, opacity: 0 },
          {
            y: 0,
            opacity: 1,
            duration: 0.9,
            ease: 'power3.out',
            scrollTrigger: { trigger: section, start: 'top 72%' },
          },
        )
      }

      cards.forEach((card, index) => {
        const media = card.querySelector('[data-gsap-media]')
        gsap.fromTo(
          card,
          { y: 100, opacity: 0, rotate: index % 2 ? 1.5 : -1.5 },
          {
            y: 0,
            opacity: 1,
            rotate: 0,
            ease: 'power3.out',
            scrollTrigger: {
              trigger: card,
              start: 'top 82%',
              end: 'top 42%',
              scrub: 0.7,
            },
          },
        )
        if (media) {
          gsap.fromTo(
            media,
            { scale: 1.15 },
            {
              scale: 1,
              ease: 'none',
              scrollTrigger: {
                trigger: card,
                start: 'top bottom',
                end: 'bottom top',
                scrub: true,
              },
            },
          )
        }
      })

      return () => ScrollTrigger.getAll().forEach((trigger) => trigger.refresh())
    },
    [items, reducedMotion],
    root,
  )

  return (
    <section ref={root} className={cn('bg-[#0b0c10] py-24 text-white md:py-32', className)}>
      <div className="container grid gap-14 lg:grid-cols-[.7fr_1.3fr]">
        <header
          data-gsap-heading
          className={cn('h-fit max-w-lg', pinHeading && 'lg:sticky lg:top-28')}
        >
          {eyebrow ? (
            <p className="text-xs font-bold uppercase tracking-[0.24em] text-primary">{eyebrow}</p>
          ) : null}
          <h2 className="mt-5 text-4xl font-bold tracking-tight md:text-6xl">{title}</h2>
          {description ? (
            <p className="mt-6 text-base leading-8 text-white/60">{description}</p>
          ) : null}
        </header>

        <div className="space-y-12 md:space-y-20">
          {items.map((item, index) => (
            <article
              data-gsap-card
              key={item.id}
              className="group overflow-hidden rounded-[2rem] border border-white/10 bg-white/[0.04]"
            >
              <div className="relative aspect-[16/10] overflow-hidden">
                <div data-gsap-media className="absolute inset-0">
                  <Image
                    src={item.image.src}
                    alt={item.image.alt}
                    fill
                    className="object-cover"
                    sizes="(min-width: 1024px) 55vw, 100vw"
                  />
                </div>
                <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent" />
                <span className="absolute left-6 top-6 rounded-full border border-white/20 bg-black/25 px-3 py-1 text-xs font-bold backdrop-blur">
                  {item.number ?? String(index + 1).padStart(2, '0')}
                </span>
              </div>
              <div className="p-7 md:p-9">
                <h3 className="text-2xl font-semibold">{item.title}</h3>
                <p className="mt-3 max-w-2xl leading-7 text-white/60">{item.description}</p>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  )
}

'use client'

import type { MouseEvent, ReactNode } from 'react'
import {
  motion,
  useMotionTemplate,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
} from 'framer-motion'
import { cn } from '@/lib/utils'

export type HoverTiltCardProps = {
  children: ReactNode
  intensity?: number
  scale?: number
  glare?: boolean
  className?: string
}

export function HoverTiltCard({
  children,
  intensity = 10,
  scale = 1.02,
  glare = true,
  className,
}: HoverTiltCardProps) {
  const reduceMotion = useReducedMotion()
  const pointerX = useMotionValue(0.5)
  const pointerY = useMotionValue(0.5)
  const rotateX = useSpring(useTransform(pointerY, [0, 1], [intensity, -intensity]), {
    stiffness: 220,
    damping: 24,
  })
  const rotateY = useSpring(useTransform(pointerX, [0, 1], [-intensity, intensity]), {
    stiffness: 220,
    damping: 24,
  })
  const glareX = useTransform(pointerX, [0, 1], ['0%', '100%'])
  const glareY = useTransform(pointerY, [0, 1], ['0%', '100%'])
  const glareBackground = useMotionTemplate`radial-gradient(circle at ${glareX} ${glareY}, white 0%, transparent 55%)`

  function updatePointer(event: MouseEvent<HTMLDivElement>) {
    const bounds = event.currentTarget.getBoundingClientRect()
    pointerX.set((event.clientX - bounds.left) / bounds.width)
    pointerY.set((event.clientY - bounds.top) / bounds.height)
  }

  function resetPointer() {
    pointerX.set(0.5)
    pointerY.set(0.5)
  }

  return (
    <motion.div
      className={cn('group relative transform-gpu overflow-hidden', className)}
      style={reduceMotion ? undefined : { rotateX, rotateY, transformPerspective: 900 }}
      whileHover={reduceMotion ? undefined : { scale }}
      onMouseMove={reduceMotion ? undefined : updatePointer}
      onMouseLeave={reduceMotion ? undefined : resetPointer}
      transition={{ type: 'spring', stiffness: 220, damping: 24 }}
    >
      {children}
      {glare && !reduceMotion ? (
        <motion.span
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 opacity-0 mix-blend-soft-light transition-opacity duration-300 group-hover:opacity-100"
          style={{ background: glareBackground }}
        />
      ) : null}
    </motion.div>
  )
}

'use client'

import { demoUrl } from '@/lib/demoOrigin'
import { cn } from '@/lib/utils'

export type IridescentRingPillProps = {
  /** Texto do botão. */
  label?: string
  href?: string
  /** URL do demo estático. */
