        <div className="relative min-h-[620px]">
          <motion.figure
            style={{ y: primaryY }}
            className="absolute left-0 top-16 h-[480px] w-[78%] overflow-hidden rounded-[2.5rem] bg-muted shadow-2xl"
          >
            <Image
              src={primaryImage.src}
              alt={primaryImage.alt}
