            </DropdownMenuItem>
          )
        })}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { useEffect, useLayoutEffect, useRef, useState, type ReactNode } from 'react'
import { cn } from '@/lib/utils'

export type PillNavItem = {
  label: string
  href: string
}

export type PillNavProps = {
  items: PillNavItem[]
  activeHref?: string
  logo?: ReactNode
  logoHref?: string
  ariaLabel?: string
  className?: string
}

const useIsomorphicLayoutEffect = typeof window === 'undefined' ? useEffect : useLayoutEffect

export function PillNav({
  items,
  activeHref,
  logo,
  logoHref = '/',
  ariaLabel = 'Navegação principal',
  className,
}: PillNavProps) {
  const pathname = usePathname()
  const [current, setCurrent] = useState(activeHref ?? pathname)
  const [hovered, setHovered] = useState<number | null>(null)
  const [highlight, setHighlight] = useState({ left: 0, width: 0, ready: false })
  const listRef = useRef<HTMLUListElement>(null)
  const itemRefs = useRef<(HTMLAnchorElement | null)[]>([])

  useEffect(() => setCurrent(activeHref ?? pathname), [activeHref, pathname])

  const activeIndex = items.findIndex((item) => item.href === current)
  const targetIndex = hovered ?? activeIndex

  useIsomorphicLayoutEffect(() => {
    const measure = () => {
      const element = itemRefs.current[targetIndex]
      if (!element) return setHighlight((value) => ({ ...value, width: 0 }))
      setHighlight({ left: element.offsetLeft, width: element.offsetWidth, ready: true })
    }
    measure()
    const observer = new ResizeObserver(measure)
    if (listRef.current) observer.observe(listRef.current)
    return () => observer.disconnect()
  }, [targetIndex, items])

  return (
    <nav
      aria-label={ariaLabel}
      className={cn(
        'inline-flex max-w-full items-center gap-2 rounded-full border bg-background/80 p-1.5 shadow-lg shadow-foreground/5 backdrop-blur',
        className,
      )}
    >
      {logo ? (
        <Link
          href={logoHref}
          className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-foreground text-background transition hover:rotate-12 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          {logo}
        </Link>
      ) : null}
      <ul
        ref={listRef}
        className="relative flex min-w-0 items-center overflow-x-auto [scrollbar-width:none]"
        onPointerLeave={() => setHovered(null)}
      >
        <li
          aria-hidden="true"
          className={cn(
            'pointer-events-none absolute inset-y-0 left-0 rounded-full bg-primary',
            highlight.ready &&
              'transition-[transform,width,opacity] duration-500 [transition-timing-function:cubic-bezier(.22,1,.36,1)]',
          )}
          style={{
            width: highlight.width,
            transform: `translateX(${highlight.left}px)`,
            transitionTimingFunction: 'cubic-bezier(.22,1,.36,1)',
            opacity: highlight.width ? 1 : 0,
          }}
        />
        {items.map((item, index) => {
          const isActive = index === activeIndex
          const isLit = index === targetIndex
          return (
            <li key={item.href} className="relative">
              <Link
                ref={(element) => {
                  itemRefs.current[index] = element
                }}
                href={item.href}
                aria-current={isActive ? 'page' : undefined}
                onPointerEnter={() => setHovered(index)}
                onFocus={() => setHovered(index)}
                onBlur={() => setHovered(null)}
                onClick={() => setCurrent(item.href)}
                className={cn(
                  'relative block whitespace-nowrap rounded-full px-4 py-2.5 text-sm font-semibold transition-colors duration-300 focus-visible:outline-none',
                  isLit ? 'text-primary-foreground' : 'text-muted-foreground hover:text-foreground',
                )}
              >
                {item.label}
              </Link>
            </li>
          )
        })}
      </ul>
    </nav>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { ChevronUp } from 'lucide-react'
import { cn } from '@/lib/utils'

export type ScrollToTopButtonProps = {
  /** Distância rolada (px) a partir da qual o botão aparece. */
  threshold?: number
  label?: string
  /** Use `static` em previews/catálogo para não flutuar sobre a página. */
  position?: 'fixed' | 'static'
  /**
   * Elemento que rola (ex.: preview do montador).
   * Quando definido, o anel acompanha esse container em vez da janela.
   */
  scrollContainer?: HTMLElement | null
  className?: string
}

const radius = 20
const circumference = 2 * Math.PI * radius

function readScrollProgress(container?: HTMLElement | null) {
  if (container) {
    const height = container.scrollHeight - container.clientHeight
    const scrollTop = container.scrollTop
    return {
      scrollTop,
      progress: height > 0 ? Math.min((scrollTop / height) * 100, 100) : 0,
    }
  }
  const height = document.documentElement.scrollHeight - window.innerHeight
  const scrollTop = window.scrollY
  return {
    scrollTop,
    progress: height > 0 ? Math.min((scrollTop / height) * 100, 100) : 0,
  }
}

/** Botão flutuante de voltar ao topo com anel de progresso da rolagem. */
export function ScrollToTopButton({
  threshold = 300,
  label = 'Voltar ao topo',
  position = 'fixed',
  scrollContainer = null,
  className,
}: ScrollToTopButtonProps) {
  const tracksLiveScroll = Boolean(scrollContainer) || position === 'fixed'
  const [visible, setVisible] = useState(!tracksLiveScroll)
  const [progress, setProgress] = useState(tracksLiveScroll ? 0 : 35)

  useEffect(() => {
    if (!tracksLiveScroll) {
      setVisible(true)
      setProgress(35)
      return
    }

    function update() {
      const { scrollTop, progress: next } = readScrollProgress(scrollContainer)
      setProgress(next)
      setVisible(scrollTop > threshold)
    }

    update()

    if (scrollContainer) {
      scrollContainer.addEventListener('scroll', update, { passive: true })
      const resizeObserver = new ResizeObserver(update)
      resizeObserver.observe(scrollContainer)
      return () => {
        scrollContainer.removeEventListener('scroll', update)
        resizeObserver.disconnect()
      }
    }

    window.addEventListener('scroll', update, { passive: true })
    window.addEventListener('resize', update)
    return () => {
      window.removeEventListener('scroll', update)
      window.removeEventListener('resize', update)
    }
  }, [threshold, scrollContainer, tracksLiveScroll])

  if (!visible) return null

  return (
    <button
      type="button"
      onClick={() => {
        if (scrollContainer) {
          scrollContainer.scrollTo({ top: 0, behavior: 'smooth' })
          return
        }
        window.scrollTo({ top: 0, behavior: 'smooth' })
      }}
      aria-label={label}
      className={cn(
        'relative z-40 flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-background text-primary shadow-lg transition hover:scale-110 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
        position === 'fixed' &&
          !scrollContainer &&
          'fixed bottom-6 right-6 animate-in fade-in-0 zoom-in-90',
        className,
      )}
    >
      <svg
        className="pointer-events-none absolute inset-0 h-12 w-12 -rotate-90"
        viewBox="0 0 48 48"
        aria-hidden
      >
        <circle
          cx="24"
          cy="24"
          r={radius}
          stroke="currentColor"
          strokeWidth="2"
          fill="none"
          className="text-muted"
        />
        <circle
          cx="24"
          cy="24"
          r={radius}
          stroke="currentColor"
          strokeWidth="2"
          fill="none"
          strokeDasharray={circumference}
          strokeDashoffset={circumference - (progress / 100) * circumference}
          strokeLinecap="round"
          className="transition-[stroke-dashoffset] duration-150"
        />
      </svg>
      <ChevronUp className="relative h-5 w-5" aria-hidden />
    </button>
  )
}

import type { ReactNode } from 'react'
import { Clock, Mail, Phone } from 'lucide-react'

import { cn } from '@/lib/utils'

export type TopBarItem = {
  label: string
  href?: string
  icon?: ReactNode
  /** Empurra o item para a direita (útil para horário). */
  align?: 'start' | 'end'
}

export type TopBarProps = {
  items: readonly TopBarItem[]
  /** Aparência da faixa. */
  variant?: 'dark' | 'slate' | 'primary'
  className?: string
}

const variants = {
  dark: {
    bar: 'border-b border-white/10 bg-[#0f172a] text-white',
    icon: 'text-amber-500',
    link: 'hover:text-amber-100',
  },
  slate: {
    bar: 'border-b border-slate-800 bg-slate-900 text-slate-300',
    icon: 'text-amber-500',
    link: 'hover:text-white',
  },
  primary: {
    bar: 'border-b border-primary-foreground/10 bg-primary text-primary-foreground',
    icon: 'text-primary-foreground/90',
    link: 'hover:opacity-90',
  },
} as const

/** Faixa superior compacta para telefone, e-mail, horário e outros atalhos. */
export function TopBar({ items, variant = 'dark', className }: TopBarProps) {
  const skin = variants[variant]
  const start = items.filter((item) => item.align !== 'end')
  const end = items.filter((item) => item.align === 'end')

  return (
    <aside className={cn('text-sm', skin.bar, className)} aria-label="Barra superior">
      <div className="container flex min-h-10 flex-wrap items-center gap-x-6 gap-y-2 py-2">
        <div className="flex flex-wrap items-center gap-x-6 gap-y-2">
          {start.map((item) => (
            <TopBarLink key={item.label} item={item} skin={skin} />
          ))}
        </div>
        {end.length ? (
          <div className="ml-auto flex flex-wrap items-center gap-x-6 gap-y-2">
            {end.map((item) => (
              <TopBarLink key={item.label} item={item} skin={skin} />
            ))}
          </div>
        ) : null}
      </div>
    </aside>
  )
}

function TopBarLink({
  item,
  skin,
}: {
  item: TopBarItem
  skin: (typeof variants)[keyof typeof variants]
}) {
  const body = (
    <>
      <span className={cn('shrink-0', skin.icon)} aria-hidden>
        {item.icon}
      </span>
      {item.label}
    </>
  )

  if (item.href) {
    return (
      <a
        href={item.href}
        className={cn(
          'inline-flex items-center gap-2 rounded-sm transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
          skin.link,
        )}
      >
        {body}
      </a>
    )
  }

  return <span className="inline-flex items-center gap-2">{body}</span>
}

/** Atalho com telefone, e-mail e horário no layout clássico. */
export function TopBarContacts({
  phone,
  phoneHref,
  email,
  hours,
  variant = 'dark',
  className,
}: {
  phone?: string
  phoneHref?: string
  email?: string
  hours?: string
  variant?: TopBarProps['variant']
  className?: string
}) {
  const items: TopBarItem[] = [
    phone
      ? {
          label: phone,
          href: `tel:${phoneHref ?? phone.replace(/\D/g, '')}`,
          icon: <Phone className="h-3.5 w-3.5" />,
        }
      : null,
    email
      ? {
          label: email,
          href: `mailto:${email}`,
          icon: <Mail className="h-3.5 w-3.5" />,
        }
      : null,
    hours
      ? {
          label: hours,
          icon: <Clock className="h-3.5 w-3.5" />,
          align: 'end' as const,
        }
      : null,
  ].filter(Boolean) as TopBarItem[]

  return <TopBar items={items} variant={variant} className={className} />
}

