  font-size: 14px;
  font-weight: 500;
  color: var(--nm-dim);
  margin-left: 4px;
}
.nm-root .nm-price-blurb {
  margin: 10px 0 0;
  font-size: 14px;
  color: var(--nm-muted);
}
.nm-root .nm-price-list {
  margin: 22px 0 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
  flex: 1;
}
.nm-root .nm-price-list li {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  font-size: 14px;
  color: var(--nm-muted);
}
.nm-root .nm-price-list li::before {
  content: '';
  width: 6px;
  height: 6px;
  margin-top: 7px;
  border-radius: 50%;
  background: var(--nm-cyan);
  box-shadow: 0 0 8px var(--nm-cyan);
  flex-shrink: 0;
}
.nm-root .nm-price-card .nm-btn {
  margin-top: 28px;
  width: 100%;
}

/* ============================================================
   CTA band
   ============================================================ */
.nm-root .nm-cta-band {
  text-align: center;
  padding: clamp(56px, 8vw, 88px) var(--nm-gutter);
  border-radius: 20px;
  border: 1px solid var(--nm-border);
  background:
    radial-gradient(ellipse at 30% 0%, rgba(124, 58, 237, 0.22), transparent 55%),
    radial-gradient(ellipse at 80% 100%, rgba(6, 182, 212, 0.16), transparent 50%),
    rgba(10, 12, 24, 0.85);
}
.nm-root .nm-cta-band h2 {
  margin: 0;
  font-size: clamp(26px, 4vw, 36px);
  font-weight: 700;
  letter-spacing: -0.03em;
}
.nm-root .nm-cta-band p {
  margin: 12px auto 0;
  max-width: 40ch;
  color: var(--nm-muted);
}
.nm-root .nm-cta-band .nm-btn { margin-top: 24px; }

/* ============================================================
   Footer
   ============================================================ */
.nm-root .nm-footer {
  border-top: 1px solid var(--nm-border);
  padding: 36px 0 48px;
}
.nm-root .nm-footer-inner {
  width: min(100%, var(--nm-max));
  margin-inline: auto;
  padding-inline: var(--nm-gutter);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}
.nm-root .nm-footer-brand {
  font-weight: 700;
  letter-spacing: -0.02em;
}
.nm-root .nm-footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
  font-size: 14px;
  color: var(--nm-dim);
}
.nm-root .nm-footer-links a:hover { color: var(--nm-text); }
.nm-root .nm-footer-copy {
  width: 100%;
  margin-top: 8px;
  font-size: 13px;
  color: var(--nm-dim);
}

/* ============================================================
   Full page shell
   ============================================================ */
.nm-root.nm-page {
  min-height: 100%;
  overflow-x: clip;
}

/* ============================================================
   Reduced motion
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  .nm-root .nm-aurora-blob,
  .nm-root .nm-btn,
  .nm-root .nm-cap-card,
  .nm-root .nm-use-card,
  .nm-root .nm-spotlight {
    animation: none !important;
    transition: none !important;
  }
  .nm-root .nm-cap-card:hover,
  .nm-root .nm-btn-primary:hover {
    transform: none;
  }
  .nm-root .nm-spotlight { display: none; }
}

/* ============================================================
   Responsive — 1200 / 768
   ============================================================ */
@media (max-width: 1200px) {
  .nm-root .nm-cap-grid,
  .nm-root .nm-use-grid,
  .nm-root .nm-price-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .nm-root .nm-dev-grid {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (max-width: 768px) {
  .nm-root .nm-nav { display: none; }
  .nm-root .nm-menu-btn { display: inline-flex; }
  .nm-root .nm-cap-grid,
  .nm-root .nm-use-grid,
  .nm-root .nm-price-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .nm-root .nm-hero h1 { font-size: clamp(32px, 9vw, 44px); }
  .nm-root .nm-footer-inner { flex-direction: column; align-items: flex-start; }
}
`

export function NimbusStyles() {
  const hoist = {
    href: 'nimbus-styles',
    precedence: 'default',
  } as React.StyleHTMLAttributes<HTMLStyleElement>
  return (
    <>
      <link
        rel="stylesheet"
        href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600&display=swap"
      />
      <style {...hoist}>{NM_CSS}</style>
    </>
  )
}

export type NimbusRootProps = {
  children: React.ReactNode
  className?: string
  style?: React.CSSProperties
}

export function NimbusRoot({ children, className, style }: NimbusRootProps) {
  return (
    <div className={['nm-root', className].filter(Boolean).join(' ')} style={style}>
      <NimbusStyles />
      {children}
    </div>
  )
}

import type { MouseEventHandler, ReactNode } from 'react'
import Link from 'next/link'
import { ArrowUpRight } from 'lucide-react'

import { cn } from '@/lib/utils'

import type { AccentTone } from './accentTones'

export type AccentButtonProps = {
  children: ReactNode
  href?: string
  tone?: AccentTone
  size?: 'md' | 'lg'
  icon?: ReactNode
  external?: boolean
  type?: 'button' | 'submit'
  disabled?: boolean
  onClick?: MouseEventHandler<HTMLElement>
  className?: string
}

const slideBase =
  'group relative inline-flex w-fit cursor-pointer items-center overflow-hidden rounded-sm font-semibold tracking-wide transition-all duration-500 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-500 focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-60'

const slideSizes = {
  md: {
    root: 'h-12 p-1.5 ps-5 pe-14 text-sm hover:ps-14 hover:pe-5',
    icon: 'right-1.5 h-9 w-9 group-hover:right-[calc(100%-42px)]',
  },
  lg: {
    root: 'h-14 p-1 ps-6 pe-20 text-base hover:ps-20 hover:pe-6 md:text-lg',
    icon: 'right-1.5 h-11 w-11 group-hover:right-[calc(100%-50px)]',
  },
}

const toneClasses: Record<AccentTone, { root: string; icon: string }> = {
  glow: {
    root: 'inline-flex items-center justify-center gap-2 rounded-full border-2 border-[#7c39cf] bg-transparent px-4 py-2 font-semibold text-[#ae89ff] transition-[color,border-color,box-shadow,background-color] duration-300 hover:border-[#c642a5] hover:bg-gradient-to-r hover:from-[#86196b] hover:to-[#5327b3] hover:text-white hover:shadow-[0_0_8px_#c642a5] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#c642a5] focus-visible:ring-offset-2 focus-visible:ring-offset-[#121212] disabled:pointer-events-none disabled:opacity-60',
    icon: '',
  },
  industrial: {
    root: 'bg-slate-900 text-white hover:bg-amber-500 hover:text-slate-950',
    icon: 'bg-white text-slate-900 group-hover:bg-slate-950 group-hover:text-white',
  },
  'industrial-dark': {
    root: 'bg-amber-500 text-slate-950 hover:bg-white',
    icon: 'bg-white text-slate-950 group-hover:bg-slate-950 group-hover:text-white',
  },
}

/** Botão de ação dos templates: contorno com gradiente (glow) ou ícone deslizante (industrial). */
export function AccentButton({
  children,
  href,
  tone = 'glow',
  size = 'md',
  icon,
  external,
  type = 'button',
  disabled,
  onClick,
  className,
}: AccentButtonProps) {
  const styles = toneClasses[tone]
  const isGlow = tone === 'glow'
  const resolvedIcon = icon ?? <ArrowUpRight className="h-4 w-4 shrink-0" aria-hidden />
  const classes = isGlow
    ? cn(styles.root, size === 'lg' && 'px-6 py-3 text-lg', className)
    : cn(slideBase, slideSizes[size].root, styles.root, className)

  const content = isGlow ? (
    <>
      {icon}
      {children}
    </>
  ) : (
    <>
      <span className="relative z-10 transition-colors duration-500">{children}</span>
      <span
        className={cn(
          'absolute flex items-center justify-center rounded-full transition-all duration-500 group-hover:rotate-12',
          slideSizes[size].icon,
          styles.icon,
        )}
        aria-hidden
      >
        {resolvedIcon}
      </span>
    </>
  )

  if (href) {
    const isExternal = external ?? /^(https?:|mailto:|tel:)/.test(href)
    if (isExternal) {
      return (
        <a
          href={href}
          className={classes}
          onClick={onClick}
          target={href.startsWith('http') ? '_blank' : undefined}
          rel={href.startsWith('http') ? 'noopener noreferrer' : undefined}
        >
          {content}
        </a>
      )
    }
    return (
      <Link href={href} className={classes} onClick={onClick}>
        {content}
      </Link>
    )
  }

  return (
    <button type={type} className={classes} onClick={onClick} disabled={disabled}>
      {content}
    </button>
  )
}

import * as React from 'react'
import type { VariantProps } from 'class-variance-authority'

import { Button, buttonVariants } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export interface ActionItem {
  label: React.ReactNode
  href: string
  variant?: VariantProps<typeof buttonVariants>['variant']
  size?: VariantProps<typeof buttonVariants>['size']
  external?: boolean
  ariaLabel?: string
  className?: string
}

export interface ActionGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  actions?: readonly ActionItem[]
  align?: 'left' | 'center' | 'right'
  mobileStack?: boolean
}

const alignments: Record<NonNullable<ActionGroupProps['align']>, string> = {
  left: 'justify-start',
  center: 'justify-center',
  right: 'justify-end',
}

export function ActionGroup({
  actions = [],
  align = 'left',
  mobileStack = false,
  children,
  className,
  ...props
}: ActionGroupProps) {
  return (
    <div
      className={cn(
        'flex flex-wrap items-center gap-3',
        alignments[align],
        mobileStack && 'max-sm:flex-col max-sm:items-stretch',
        className,
      )}
      {...props}
    >
      {actions.map((action) => (
        <Button
          key={`${action.href}-${String(action.label)}`}
          asChild
          variant={action.variant}
          size={action.size}
          className={action.className}
        >
          <a
            href={action.href}
            aria-label={action.ariaLabel}
            target={action.external ? '_blank' : undefined}
            rel={action.external ? 'noopener noreferrer' : undefined}
          >
            {action.label}
          </a>
        </Button>
      ))}
      {children}
    </div>
  )
}

