  line-height: 0.98;
}
.vl-root .vl-voyage-p {
  position: absolute;
  right: var(--vl-edge);
  bottom: 104px;
  width: min(400px, 30vw);
}
.vl-root .vl-voyage-p p {
  margin: 0;
  font-size: 16px;
  line-height: 1.75;
  color: rgba(244, 239, 230, 0.88);
}
