  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--vl-accent);
}

/* destinations */
.vl-root .vl-dest-h {
  position: absolute;
  left: var(--vl-gutter);
  top: 150px;
  width: min(560px, 80vw);
}
