  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}
.vl-root .vl-tile {
  padding: 26px 24px;
  border-radius: 22px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-height: 170px;
  transition: background 0.3s;
}
.vl-root .vl-tile:hover { background: rgba(8, 15, 22, 0.62); }
.vl-root .vl-tile .vl-top {
  display: flex;
  justify-content: space-between;
