  border-radius: 32px 32px 0 0;
  border: 1px solid rgba(244, 239, 230, 0.08);
  border-bottom: 0;
  box-shadow: 0 -40px 80px rgba(0, 0, 0, 0.4);
}
.vl-root .vl-reserve-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr);
