}
.vl-root .vl-qf .vl-g2 {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}
.vl-root .vl-qf label {
  display: block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(244, 239, 230, 0.6);
  margin-bottom: 8px;
}
.vl-root .vl-qf input,
.vl-root .vl-qf select {
  width: 100%;
  height: 52px;
  padding: 0 16px;
  background: #121b25;
  border: 1px solid rgba(244, 239, 230, 0.14);
